  looking_ahead = excluded.looking_ahead;

-- postpartum week 130: How much thiamine (vitamin B1) does your toddler need, and where does it come from?
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   130,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'How much thiamine (vitamin B1) does your toddler need, and where does it come from?',
   '"Thiamine helps turn your toddler''s food into the energy their body and brain run on — and for most families, whole grains, dal and a little variety alongside rice already provide it through ordinary meals."',
   'Thiamine, also called vitamin B1, is a water-soluble vitamin your toddler''s body uses as a coenzyme in energy metabolism, helping convert the carbohydrates, fats and protein in food into usable energy, and supporting normal nerve function. Thiamine deficiency is rare in toddlers eating a varied diet — the toddler-relevant caution isn''t about any single meal, but about a diet that relies very heavily on polished white rice with little variety, since milling removes most of rice''s natural thiamine. Food sources include whole grains, pulses, nuts and seeds, meat, and fortified cereals — many of which are already part of ordinary Indian family meals. Using this shared menu These meals are designed so the family can begin with the same basic food. Serve the mother a satisfying adult portion, including enough protein, vegetables and energy for her own needs. Adapt only the toddler''s portion to their chewing ability: remove bones and hard seeds, reduce salt and chilli, and cut or soften food as needed. A toddler does not need every family food mashed if they can already manage ordinary family textures safely.',
   'If your toddler''s diet relies very heavily on polished white rice with little dietary variety: actively include more whole grain, dal, nut or fortified-food variety this week — this is covered further on Day 5. If your child takes long-term diuretic medication such as furosemide: Some medicines, including long-term furosemide, may affect thiamine status. Do not change the medicine, diet or supplements independently; ask your child''s treating team whether any monitoring or supplementation is needed. If you manage diabetes, PCOS or insulin resistance: keep your prescribed meal, monitoring and medication schedule steady, and pair rice, roti, fruit or toast with protein or fibre where practical. If you manage high blood pressure: keep added salt, pickles, papad and packaged sauces within the limits advised for you. If you take thyroid medication: continue it exactly as prescribed and maintain any required separation from iron or calcium supplements. If you are being treated for anaemia: continue prescribed iron, and follow the timing instructions provided for taking it around tea, coffee, calcium or thyroid medication. None of this needs to turn every meal into detective work. A clear diagnosis, from the right professional, is what actually tells you which foods or proportions are the concern. Your seven-day shared family menu Choose either option at each meal according to your family''s preferences, available ingredients and dietary pattern. A and B are alternatives; you do not need to prepare both. ———————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————- This week''s menu doesn''t change to specially feature thiamine — it''s the same kind of shared family meal this series always uses. Whole grain options like whole wheat roti or paratha, dal, and ground sunflower seed are useful everyday thiamine sources; ordinary polished white rice provides comparatively little, so pairing rice with dal, a whole grain, seeds prepared safely, meat where eaten, or an appropriately fortified food — as this menu already does — is a practical everyday habit rather than something to add specially. Wash all produce thoroughly with reliably safe water, and cook ingredients fully. ———————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————-',
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Thiamine''s role: turning food into energy", "notes": "Thiamine, also known as vitamin B1, is a water-soluble vitamin your toddler''s body uses as a coenzyme — a helper molecule — in energy metabolism. In its active form, thiamine diphosphate, it''s required by several enzymes that convert the carbohydrates, fats and protein in food into usable energy, and it also supports normal nerve function. The body stores only small amounts of thiamine, so it needs a regular dietary supply. However, this does not mean parents need to provide a thiamine-rich food at every meal; a varied eating pattern across the week is sufficient for most toddlers.", "breakfast_a": "Oats porridge with grated apple mixed through, served with milk", "breakfast_b": "Oats porridge with grated apple mixed through and a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Soft roti with arhar dal and soft-cooked potato, finely mashed", "lunch_b": "Soft roti with arhar dal, soft tofu, finely crumbled, and soft-cooked potato, finely mashed, if soy has already been introduced and tolerated", "nourishment_break_a": "A small bowl of curd with soft, ripe apple, peeled, cored and finely grated", "nourishment_break_b": "Finely ground sunflower seed mixed into a small bowl of plain curd, if sunflower seed has already been introduced and tolerated", "dinner_a": "Rice with moong dal and soft-cooked turnip (shalgam), finely mashed", "dinner_b": "Rice with moong dal, boneless, finely shredded chicken and soft-cooked turnip (shalgam), finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 2, "title": "How much thiamine does your toddler need?", "notes": "The US NIH recommends 0.5 mg of thiamine a day for children aged 1-3 years, a figure that matches WHO/FAO''s own recommended intake for the same age group. ICMR-NIN''s 2020 recommendation for Indian children in this age group is higher, at 0.7 mg a day — a genuine difference between authorities worth naming honestly, rather than a sign that one figure is simply wrong. No Tolerable Upper Intake Level has been established for thiamine because harmful effects from high intakes have not been consistently reported and the available evidence is limited. This should not be interpreted as a reason to give a toddler high-dose supplements. Supplements should be used only when recommended by the child''s healthcare team. None of this means parents need to calculate a daily total — it means an ordinary varied diet, described over the next few days, comfortably covers what''s needed.", "breakfast_a": "Whole wheat paratha with grated bottle gourd (lauki) mixed through, served with plain curd", "breakfast_b": "Whole wheat paratha with grated bottle gourd (lauki) mixed through and a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft paratha with masoor dal and soft-cooked radish (mooli), finely chopped", "lunch_b": "Soft paratha with masoor dal, a fully cooked egg curry and soft-cooked radish (mooli), finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe watermelon, seeds removed and finely chopped", "nourishment_break_b": "Finely ground roasted chana (bhuna chana) mixed into a small bowl of warm milk", "dinner_a": "Soft khichdi with chana dal and soft-cooked green peas (mataar), finely mashed", "dinner_b": "Soft khichdi with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked green peas (mataar), finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 3, "title": "Where thiamine comes from in food", "notes": "Thiamine occurs naturally in whole grains, pulses, nuts and seeds, and meat — pork is a particularly rich source where it''s eaten — and is added to many fortified breakfast cereals. A grain''s natural thiamine sits mostly in its outer layers and germ, which milling removes; whole wheat and other whole grains keep meaningfully more thiamine than heavily milled or polished grains. This matters directly for a rice-based Indian diet: ordinary polished white rice loses most of its natural thiamine during milling. Parboiling — part-cooking rice in the husk before milling — drives some thiamine from the outer bran into the grain itself, so parboiled rice retains somewhat more than regular milled white rice, though still less than a true whole grain. Sunflower seeds and pulses add further everyday amounts.", "breakfast_a": "Bajra (pearl millet) porridge with mashed banana mixed through, served with milk", "breakfast_b": "Bajra (pearl millet) porridge with mashed banana mixed through and a small portion of mild, fully cooked minced mutton, finely crumbled", "lunch_a": "Rice with mixed dal and soft-cooked sweet potato (shakarkandi), finely mashed", "lunch_b": "Rice with mixed dal, a fully cooked, lower-mercury fish curry, finely flaked and carefully checked for bones, and soft-cooked sweet potato (shakarkandi), finely mashed", "nourishment_break_a": "A small bowl of curd with pomegranate arils, thoroughly crushed or blended to a texture the toddler can safely manage", "nourishment_break_b": "Fresh grated coconut mixed into a small bowl of plain curd", "dinner_a": "Soft roti with arhar dal and soft-cooked sweet corn (bhutta) kernels, finely mashed", "dinner_b": "Soft roti with arhar dal, soft tofu, finely crumbled, and soft-cooked sweet corn (bhutta) kernels, finely mashed, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 4, "title": "Why thiamine deficiency from diet alone is rare in toddlers", "notes": "Thiamine deficiency can cause beriberi, affecting the nervous system and, in severe cases, the heart and circulation. Infantile beriberi classically affects young breastfed infants whose mothers are severely thiamine-deficient, but deficiency can also occur in other circumstances involving profoundly limited intake, prolonged vomiting, malabsorption or serious undernutrition. For a toddler who is growing as expected and eating a reasonably varied diet, deficiency is unlikely. Persistent feeding restriction, recurrent vomiting, poor growth or unexplained weakness deserves medical assessment rather than dietary self-treatment.", "breakfast_a": "Multigrain dosa, soft, with a smooth, mild coconut chutney", "breakfast_b": "Multigrain dosa, soft, with a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Soft paratha with moong dal and soft-cooked brinjal (baingan), finely mashed", "lunch_b": "Soft paratha with moong dal, boneless, finely shredded chicken and soft-cooked brinjal (baingan), finely mashed", "nourishment_break_a": "A small bowl of curd with soft, ripe pear, peeled, cored and finely chopped", "nourishment_break_b": "Finely ground white sesame (safed til) mixed into a small bowl of warm milk, if sesame has already been introduced and tolerated", "dinner_a": "Rice with masoor dal and soft-cooked mushroom, finely chopped", "dinner_b": "Rice with masoor dal, a fully cooked egg curry and soft-cooked mushroom, finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 5, "title": "The exception: rice-heavy diets and other risk factors", "notes": "General reassurance doesn''t apply to every toddler equally. A diet that relies very heavily on regular polished white rice, with little whole grain, pulses, nuts or fortified food for variety, is a genuinely different situation — this pattern is a documented population-level risk factor for thiamine inadequacy, and it''s worth actively including some of the more thiamine-rich foods described this week rather than assuming rice alone is enough. Some medicines, including long-term furosemide, may affect thiamine status. Do not change the medicine, diet or supplements independently; ask your child''s treating team whether any monitoring or supplementation is needed. Other situations needing individual assessment include prolonged or recurrent vomiting, significant malabsorption, severe undernutrition, or an extremely restricted diet. These concerns require healthcare guidance; they are not a reason to start high-dose thiamine independently. Outside these specific circumstances, thiamine deficiency isn''t something to actively watch for in a toddler eating a varied diet.", "breakfast_a": "Poha (flattened rice) with mixed finely chopped vegetables and finely ground peanut mixed through, lightly spiced and fully cooked, served with plain curd, if peanut has already been introduced and tolerated", "breakfast_b": "Poha (flattened rice) with mixed finely chopped vegetables and finely ground peanut mixed through, lightly spiced and fully cooked, served with a soft scrambled egg (bhurji), fully cooked, on the side, if peanut has already been introduced and tolerated", "lunch_a": "Soft roti with chana dal and soft-cooked raw papaya (kachcha papita), finely mashed", "lunch_b": "Soft roti with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked raw papaya (kachcha papita), finely mashed", "nourishment_break_a": "A small bowl of curd with soft, ripe mango, peeled and mashed", "nourishment_break_b": "Finely ground poppy seed (khuskhus) mixed into a small bowl of plain curd, if poppy seed has already been introduced and tolerated", "dinner_a": "Rice with arhar dal and soft-cooked french beans (phalli), finely chopped", "dinner_b": "Rice with arhar dal, a fully cooked, lower-mercury fish curry, finely flaked and carefully checked for bones, and soft-cooked french beans (phalli), finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 6, "title": "Where thiamine shows up in an ordinary Indian day", "notes": "Whole wheat roti and paratha, brown or less-milled rice, parboiled rice, dals of every kind, and sunflower seeds offered ground are all useful everyday thiamine sources in an Indian kitchen. Fortified breakfast cereals, when your family already uses them, are a meaningful source too. None of this needs a special ''thiamine meal'' or replacing rice at every meal — offering some whole grain, dal, nuts or seeds alongside rice across the week is enough for most families.", "breakfast_a": "Sooji (semolina) uttapam with finely grated cucumber mixed through, served with a mild dal accompaniment", "breakfast_b": "Sooji (semolina) uttapam with finely grated cucumber mixed through and a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Soft paratha with mixed dal and soft-cooked bitter gourd (karela), finely chopped", "lunch_b": "Soft paratha with mixed dal, soft tofu, finely crumbled, and soft-cooked bitter gourd (karela), finely chopped, if soy has already been introduced and tolerated", "nourishment_break_a": "A small bowl of curd with soft, ripe sweet lime (mosambi) segments, seeds and membrane removed, finely chopped", "nourishment_break_b": "Finely ground peanut mixed into a small bowl of plain curd, if peanut has already been introduced and tolerated", "dinner_a": "Soft khichdi with moong dal and soft-cooked spring onion (hara pyaz), finely chopped", "dinner_b": "Soft khichdi with moong dal, boneless, finely shredded chicken and soft-cooked spring onion (hara pyaz), finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 7, "title": "Bringing it together", "notes": "Thiamine is another example of a nutrient this series can mostly reassure you about: it plays a real, specific role turning your toddler''s food into usable energy and supporting normal nerve function. Whole grains, pulses, nuts, seeds and fortified foods all contribute alongside rice, and reference intakes differ modestly between authorities without pointing to any real difference in what a toddler actually needs. Parents do not need to calculate a daily total when their toddler eats a varied diet. The one thing worth remembering precisely is the exception: a diet that leans almost entirely on polished white rice with little variety is where actively including a few more of this week''s foods is worth the effort.", "breakfast_a": "Rava (semolina) idli with finely grated zucchini mixed through, served with plain curd or sambar", "breakfast_b": "Rava (semolina) idli with finely grated zucchini mixed through and a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Rice with masoor dal and soft-cooked flat beans (sem), finely chopped", "lunch_b": "Rice with masoor dal, a fully cooked egg curry and soft-cooked flat beans (sem), finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe custard apple (sitaphal), all seeds thoroughly removed and mashed", "nourishment_break_b": "Roasted moong, ground to a smooth powder and mixed thoroughly into a small bowl of warm milk", "dinner_a": "Soft roti with chana dal and soft-cooked tomato, finely mashed", "dinner_b": "Soft roti with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked tomato, finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food. Looking back over this week''s meals, how much of your family''s rice was matched by roti, dal, whole grain, or another variety across the week?", "still_hungry": null}]'::jsonb,
   'You may not need to change anything dramatic this week. Instead, notice how much of your family''s rice is already paired with roti, dal, whole grain or fortified food across the week. If your toddler eats only a very limited range of foods, or you''re concerned about growth or feeding, discuss the overall pattern with their healthcare team.',
   'Next week continues Phase 5 with another part of life beyond the first year, carrying forward this week''s approach: a few well-evidenced adjustments, and permission to let go of the rest.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 131: Understanding your toddler's growth chart — what percentiles actually mean, and when a number is worth asking about
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   131,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Understanding your toddler''s growth chart — what percentiles actually mean, and when a number is worth asking about',
   '"A percentile is a position on a chart, not a grade. Healthy children naturally grow at different percentiles, and your child''s pattern over time matters more than chasing one particular number. Measurements at the extremes or a meaningful change in the pattern still deserve professional interpretation."',
   'Growth charts compare your toddler''s measurements with an appropriate reference standard. Age-based charts show how weight, length or height, BMI or head circumference compares with children of the same age and sex. Weight-for-length or weight-for-height instead examines whether weight is proportionate to the child''s measured length or height. In most Indian clinical settings, including guidance from the Indian Academy of Pediatrics, the WHO Child Growth Standards are used for children under five. These standards describe how children should grow under good conditions, built partly from data on Indian children among others, rather than simply describing how one population happened to grow. There is no single ''ideal'' percentile: a child who consistently tracks along the 10th percentile can be just as healthy as one tracking along the 90th. What matters most to your child''s healthcare team is the trend over time, not any single number. Using this shared menu These meals are designed so the family can begin with the same basic food. Serve the mother a satisfying adult portion, including enough protein, vegetables and energy for her own needs. Adapt only the toddler''s portion to their chewing ability: remove bones and hard seeds, reduce salt and chilli, and cut or soften food as needed. A toddler does not need every family food mashed if they can already manage ordinary family textures safely.',
   'If you are concerned about a measurement, or your toddler shows a sustained change in their usual growth pattern: bring the actual measurements and dates to your child''s healthcare team. The meaning depends on which measurement changed, the chart used and the child''s wider health — not simply the number of printed lines crossed. If you manage diabetes, PCOS or insulin resistance: keep your prescribed meal, monitoring and medication schedule steady, and pair rice, roti, fruit or toast with protein or fibre where practical. If you manage high blood pressure: keep added salt, pickles, papad and packaged sauces within the limits advised for you. If you take thyroid medication: continue it exactly as prescribed and maintain any required separation from iron or calcium supplements. If you are being treated for anaemia: continue prescribed iron, and follow the timing instructions provided for taking it around tea, coffee, calcium or thyroid medication. None of this needs to turn every meal into detective work. A clear diagnosis, from the right professional, is what actually tells you which foods or proportions are the concern. Your seven-day shared family menu Choose either option at each meal according to your family''s preferences, available ingredients and dietary pattern. A and B are alternatives; you do not need to prepare both. ————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————- This week''s menu doesn''t change specially for this topic — it''s the same kind of shared family meal this series always uses. A growth-chart reading on its own is not a reason to add or restrict particular foods. Continue offering a balanced variety unless your child''s healthcare team has identified a growth or medical concern and recommended an individualised plan. Wash all produce thoroughly with reliably safe water, and cook ingredients fully. ————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————-',
   NULL,
   NULL,
   '[{"day_number": 1, "title": "What a percentile actually means", "notes": "Growth charts compare a child''s measurements with an appropriate reference standard. Weight-for-age, length or height-for-age, BMI-for-age and head-circumference-for-age are age- and sex-specific. Weight-for-length or weight-for-height instead examines whether weight is proportionate to the child''s measured length or height. Each chart answers a different question, which is why healthcare professionals interpret several measurements together. In most Indian clinical settings, growth is plotted against the WHO Child Growth Standards, used for children under five, including in guidance from the Indian Academy of Pediatrics. These standards are prescriptive: built from data on how healthy, well-fed children from several countries — including India — actually grew under good conditions, describing how children should grow rather than merely how one population happened to grow historically.", "breakfast_a": "Vegetable paratha with grated carrot mixed through, served with plain curd", "breakfast_b": "Vegetable paratha with grated carrot mixed through and a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Soft roti with arhar dal and soft-cooked cauliflower, finely chopped", "lunch_b": "Soft roti with arhar dal, soft tofu, finely crumbled, and soft-cooked cauliflower, finely chopped, if soy has already been introduced and tolerated", "nourishment_break_a": "A small bowl of curd with soft, ripe banana, mashed or cut lengthwise and then into small, manageable pieces", "nourishment_break_b": "Finely ground walnut mixed into a small bowl of plain curd, if walnut has already been introduced and tolerated", "dinner_a": "Rice with moong dal and soft-cooked cabbage, finely shredded", "dinner_b": "Rice with moong dal, boneless, finely shredded chicken and soft-cooked cabbage, finely shredded If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 2, "title": "Why there''s no ''ideal'' number", "notes": "There is no ''ideal'' percentile to aim for. A toddler who consistently tracks along the 10th percentile can be just as healthy as one tracking along the 90th — unlike a school grade, higher isn''t automatically better on a growth chart. What matters most is consistency: a child following their own curve over time, rather than any single number on a given day. A lower percentile does not, by itself, mean poor feeding or malnutrition, and a higher percentile does not, by itself, mean a healthier or better-fed child. Body size varies naturally, including with parents'' and siblings'' build. Measurements at the extremes, or a meaningful change in your child''s own pattern, still deserve professional interpretation rather than reassurance alone.", "breakfast_a": "Jowar (sorghum) porridge with mashed banana mixed through, served with milk", "breakfast_b": "Jowar (sorghum) porridge with mashed banana mixed through and a small portion of mild, fully cooked minced mutton, finely crumbled", "lunch_a": "Soft paratha with masoor dal and thoroughly cooked spinach (palak), finely chopped", "lunch_b": "Soft paratha with masoor dal, a fully cooked egg curry and thoroughly cooked spinach (palak), finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe orange segments, seeds and tough membranes removed, cut into small, soft, manageable pieces", "nourishment_break_b": "Finely ground almond mixed into a small bowl of warm milk, if almond has already been introduced and tolerated", "dinner_a": "Soft khichdi with chana dal and soft-cooked pumpkin, finely mashed", "dinner_b": "Soft khichdi with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked pumpkin, finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 3, "title": "Why one chart doesn''t tell the whole story", "notes": "Weight-for-age, height-for-age, weight-for-length or weight-for-height, BMI-for-age where used, and head-circumference-for-age are different charts that measure different aspects of growth. Looking at only one in isolation can be misleading. A toddler who is both lighter and shorter than average may have a weight that is proportionate to their height. That can be reassuring in one respect, but the healthcare professional will still consider height-for-age, growth velocity, family build and the child''s overall health before interpreting the pattern. This is why a healthcare professional usually looks at more than one chart together, alongside how your child is developing, feeding and behaving, rather than a single measurement in isolation.", "breakfast_a": "Vegetable idli with finely mashed beetroot mixed through, served with plain curd or sambar", "breakfast_b": "Vegetable idli with finely mashed beetroot mixed through and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Rice with mixed dal and soft-cooked ridge gourd (turai), finely chopped", "lunch_b": "Rice with mixed dal, a fully cooked, lower-mercury fish curry, finely flaked and carefully checked for bones, and soft-cooked ridge gourd (turai), finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe guava, with hard seeds removed or sieved out, mashed to a manageable texture", "nourishment_break_b": "Finely ground black sesame (kala til) mixed into a small bowl of warm milk, if black sesame has already been introduced and tolerated", "dinner_a": "Soft roti with arhar dal and soft-cooked snake gourd (chichinda), finely chopped", "dinner_b": "Soft roti with arhar dal, soft tofu, finely crumbled, and soft-cooked snake gourd (chichinda), finely chopped, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 4, "title": "What ''crossing percentile lines'' means", "notes": "Some movement on a growth chart can occur normally, particularly during early childhood. Clinicians pay closer attention to a sustained or substantial change in weight, length or height, weight-for-length or height, or BMI-for-age — especially when it is accompanied by feeding difficulties, illness, developmental concerns or changes in energy and behaviour. Counting percentile lines can be a useful prompt, but it is not a diagnosis and does not have exactly the same meaning on every chart.", "breakfast_a": "Vegetable upma with grated radish (mooli) mixed through, served with plain curd", "breakfast_b": "Vegetable upma with grated radish (mooli) mixed through and soft scrambled egg (bhurji), lightly spiced and fully cooked, on the side", "lunch_a": "Soft paratha with moong dal and soft-cooked carrot (gajar), finely grated", "lunch_b": "Soft paratha with moong dal, boneless, finely shredded chicken and soft-cooked carrot (gajar), finely grated", "nourishment_break_a": "A small bowl of curd with soft, ripe papaya, deseeded and finely chopped", "nourishment_break_b": "Finely ground pumpkin seed mixed into a small bowl of plain curd, if pumpkin seed has already been introduced and tolerated", "dinner_a": "Rice with masoor dal and soft-cooked green beans, finely chopped", "dinner_b": "Rice with masoor dal, a fully cooked egg curry and soft-cooked green beans, finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 5, "title": "The exception: when to bring a growth concern to your child''s healthcare team", "notes": "General reassurance doesn''t replace individual medical judgement. Bring any specific growth concern to your child''s healthcare team rather than trying to resolve it from the chart alone — particularly if your toddler shows a sustained or substantial change from their previous growth pattern, has lost weight outright rather than simply gained more slowly, or shows reduced appetite, low energy, recurrent illness or a change in behaviour alongside a growth change. A single reading that worries you is also worth raising, even without a clear trend yet — your own observations, alongside your child''s actual measurements over time, are both useful information for their healthcare team.", "breakfast_a": "Wheat dalia (broken wheat) porridge with grated pear mixed through, served with milk", "breakfast_b": "Wheat dalia (broken wheat) porridge with grated pear mixed through and a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft roti with chana dal and soft-cooked bottle gourd (lauki), finely mashed", "lunch_b": "Soft roti with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked bottle gourd (lauki), finely mashed", "nourishment_break_a": "A small bowl of curd with soft, seedless grapes, quartered lengthwise", "nourishment_break_b": "Finely ground watermelon seed mixed into a small bowl of warm milk, if watermelon seed has already been introduced and tolerated", "dinner_a": "Rice with arhar dal and soft-cooked tinda (apple gourd), finely mashed", "dinner_b": "Rice with arhar dal, a fully cooked, lower-mercury fish curry, finely flaked and carefully checked for bones, and soft-cooked tinda (apple gourd), finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 6, "title": "How often to actually check, and letting go of the scale", "notes": "For most toddlers without a known growth concern, measurements taken at scheduled healthcare visits are generally sufficient. Frequent home weighing can be difficult to perform accurately and may increase anxiety without clarifying the longer-term pattern. If your child''s healthcare team is actively monitoring growth, follow the measurement schedule they provide rather than applying a general rule.", "breakfast_a": "Moong dal chilla with finely grated potato mixed through, served with plain curd", "breakfast_b": "Moong dal chilla with finely grated potato mixed through and a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Soft paratha with mixed dal and soft-cooked raw jackfruit (kathal), finely chopped", "lunch_b": "Soft paratha with mixed dal, soft tofu, finely crumbled, and soft-cooked raw jackfruit (kathal), finely chopped, if soy has already been introduced and tolerated", "nourishment_break_a": "A small bowl of curd with soft, ripe fresh fig, stem removed and mashed or cut into small, soft pieces", "nourishment_break_b": "Finely ground fennel seed (saunf) mixed into a small bowl of plain curd", "dinner_a": "Soft khichdi with moong dal and soft-cooked capsicum, finely chopped", "dinner_b": "Soft khichdi with moong dal, boneless, finely shredded chicken and soft-cooked capsicum, finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 7, "title": "Bringing it together", "notes": "A growth chart is one useful tool your child''s healthcare team uses among several, not a verdict to interpret on your own. A percentile is a position, not a grade, and a child can be healthy at many different percentiles. Measurements at the extremes, or a meaningful change in the pattern, still deserve professional interpretation rather than reassurance alone. What matters most is your toddler''s own trend over time — growing consistently, eating a varied diet, developing as expected — rather than any single number on any single day. When something about growth specifically worries you, your child''s healthcare team, with the fuller picture in front of them, is the right place to bring it.", "breakfast_a": "Besan (gram flour) chilla with finely grated tomato mixed through, served with a mild dal accompaniment", "breakfast_b": "Besan (gram flour) chilla with finely grated tomato mixed through and a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Rice with masoor dal and soft-cooked cluster beans (gawar), finely chopped", "lunch_b": "Rice with masoor dal, a fully cooked egg curry and soft-cooked cluster beans (gawar), finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe jamun (Indian black plum), skin and seed removed, finely mashed", "nourishment_break_b": "Finely ground cashew mixed into a small bowl of warm milk, if cashew has already been introduced and tolerated", "dinner_a": "Soft roti with chana dal and soft-cooked beetroot, finely mashed", "dinner_b": "Soft roti with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked beetroot, finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food. Next time you see your toddler''s growth chart, notice whether you''re looking for a single ''good'' number, or for their own steady trend over time.", "still_hungry": null}]'::jsonb,
   'You don''t need to memorise a percentile number this week. Instead, notice whether you''re looking at your toddler''s chart for a single ''good'' reading or for their own steady trend. If your toddler eats only a very limited range of foods, or you''re concerned about growth or feeding, discuss the overall pattern with their healthcare team.',
   'Next week continues Phase 5 with another part of life beyond the first year, carrying forward this week''s approach: a few well-evidenced adjustments, and permission to let go of the rest.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 132: How much riboflavin (vitamin B2) does your toddler need, and where does it come from?
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   132,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'How much riboflavin (vitamin B2) does your toddler need, and where does it come from?',
   '"Riboflavin helps turn your toddler''s food into energy and keeps skin, eyes and the lining of the mouth healthy — and an ordinary varied week, with some milk, curd, egg and dal, already provides it."',
   'Riboflavin, or vitamin B2, is a nutrient your toddler''s body uses to turn food into energy, and to keep skin, eyes and the lining of the mouth healthy. It''s rarely a concern on its own for a toddler eating a reasonably varied diet — some dairy, egg or dal most days, plus the odd whole grain, green or nut in a safe form. The one situation genuinely worth a closer look is a diet with very little dairy, egg or other animal-source food, covered later this week. Using this shared menu These meals are designed so the family can begin with the same basic food. Serve the mother a satisfying adult portion, including enough protein, vegetables and energy for her own needs. Adapt only the toddler''s portion to their chewing ability: remove bones and hard seeds, reduce salt and chilli, and cut or soften food as needed. A toddler does not need every family food mashed if they can already manage ordinary family textures safely.',
   'If your toddler''s diet includes very little dairy, egg or other animal-source food: this week''s genuine exception — see Day 5 for what actually matters. If you manage diabetes, PCOS, high blood pressure, thyroid concerns or anaemia, keep following your prescribed plan, monitoring and medication timing as usual — nothing about this week''s menu or theme changes that guidance. None of this needs to turn every meal into detective work. A clear diagnosis, from the right professional, is what actually tells you which foods or proportions are the concern. Your seven-day shared family menu Choose either option at each meal according to your family''s preferences, available ingredients and dietary pattern. A and B are alternatives; you do not need to prepare both. ————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————— This week''s menu doesn''t change to specially feature riboflavin — it''s the same kind of shared family meal this series always uses, built mostly from foods your family probably already eats. Milk, curd, paneer and eggs are the most reliable everyday riboflavin sources; dal, whole grains, almonds and leafy greens add further amounts. Wash all produce thoroughly with reliably safe water, and cook ingredients fully. —————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————————',
   NULL,
   NULL,
   '[{"day_number": 1, "title": "What riboflavin actually does", "notes": "Riboflavin, or vitamin B2, is one of several B vitamins your toddler''s body needs in small, regular amounts. Its main job is helping cells turn the food your toddler eats into usable energy. It also plays a part in keeping skin, eyes and the lining of the mouth healthy, and in normal growth. The body doesn''t store much of it, so it needs a steady supply — but that doesn''t mean every meal needs to contain a riboflavin-rich food. Across a week, an ordinary varied diet takes care of it.", "breakfast_a": "Ragi (finger millet) porridge with mashed banana mixed through, served with milk", "breakfast_b": "Ragi (finger millet) porridge with mashed banana mixed through and a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Soft roti with moong dal and soft-cooked potato, finely mashed", "lunch_b": "Soft roti with moong dal, boneless, finely shredded chicken and soft-cooked potato, finely mashed", "nourishment_break_a": "A small bowl of curd with soft, ripe apple, peeled, cored and finely chopped", "nourishment_break_b": "Finely ground almond mixed into a small bowl of plain curd, if almond has already been introduced and tolerated", "dinner_a": "Rice with chana dal and thoroughly cooked spinach (palak), finely chopped", "dinner_b": "Rice with chana dal, soft tofu, finely crumbled, and thoroughly cooked spinach (palak), finely chopped, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 2, "title": "How much riboflavin does my toddler actually need?", "notes": "You don''t need to calculate milligrams at home. For context: the US NIH and WHO/FAO both put the daily target for a 1-3-year-old at around 0.5 mg, while ICMR-NIN''s Indian recommendation is reported considerably higher, at roughly 1.1 mg — a real difference between authorities this document names honestly rather than resolving. There''s no known risk from getting more than this through ordinary food, and no reason to reach for a high-dose supplement; supplements are worth using only if your child''s healthcare team specifically recommends one. Whichever number you use, the practical takeaway is the same: offer a varied diet across the week, and you''re very likely covering it.", "breakfast_a": "Paneer paratha with grated carrot mixed through, served with plain curd", "breakfast_b": "Paneer paratha with grated carrot mixed through and a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft paratha with arhar dal and soft-cooked tomato, finely mashed", "lunch_b": "Soft paratha with arhar dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked tomato, finely mashed", "nourishment_break_a": "A small bowl of curd with soft, ripe banana, mashed", "nourishment_break_b": "Finely ground peanut mixed into a small bowl of warm milk, if peanut has already been introduced and tolerated", "dinner_a": "Soft khichdi with masoor dal and soft-cooked cauliflower, finely chopped", "dinner_b": "Soft khichdi with masoor dal, a fully cooked egg curry and soft-cooked cauliflower, finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 3, "title": "Is your toddler''s ordinary week already covering this?", "notes": "This is worth checking without a food diary or a calculator. Across a typical week, does your toddler have milk, curd or paneer on most days? Egg, if your family eats it? Dal most days? And at least some whole grain, leafy green, or nuts or seeds prepared safely, now and then? If most of that sounds familiar, an ordinary week is probably already covering what your toddler needs — this week''s menu is simply one example of what that pattern can look like, not a special ''riboflavin diet'' to follow instead of your usual food.", "breakfast_a": "Idli (soft), served with sambar or curd", "breakfast_b": "Idli (soft), served with a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Rice with mixed dal and soft-cooked green peas (mataar), finely mashed", "lunch_b": "Rice with mixed dal, a fully cooked, lower-mercury fish curry, finely flaked and carefully checked for bones, and soft-cooked green peas (mataar), finely mashed", "nourishment_break_a": "A small bowl of curd with soft, ripe papaya, deseeded and finely mashed", "nourishment_break_b": "Finely ground white sesame (safed til) mixed into a small bowl of plain curd, if sesame has already been introduced and tolerated", "dinner_a": "Soft roti with moong dal and soft-cooked green beans, finely chopped", "dinner_b": "Soft roti with moong dal, boneless, finely shredded chicken and soft-cooked green beans, finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 4, "title": "Where riboflavin comes from", "notes": "Milk, curd and paneer are the most reliable, familiar sources in an Indian kitchen. Egg and mushroom add meaningful amounts too. Dal, whole grains, green leafy vegetables and almonds contribute further amounts — usually smaller than dairy or egg on their own, but they add up across a week. None of this needs a special shopping list; it''s mostly what an ordinary Indian family already eats. Worth knowing: Riboflavin breaks down when exposed to light — part of why milk isn''t usually sold or stored in clear glass. Keeping milk in an opaque container, out of direct sunlight, is a small, genuinely useful habit. For you: You don''t need to cook separately for yourself this week. The same milk, curd, paneer, egg and dal on your toddler''s plate are simply your food too — sharing one pot, rather than preparing a second meal just for you, is what this series has meant by a shared family menu all along.", "breakfast_a": "Missi roti, soft, served with a mild dal accompaniment", "breakfast_b": "Missi roti, soft, served with a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Soft paratha with masoor dal and soft-cooked bottle gourd (lauki), finely mashed", "lunch_b": "Soft paratha with masoor dal, soft tofu, finely crumbled, and soft-cooked bottle gourd (lauki), finely mashed, if soy has already been introduced and tolerated", "nourishment_break_a": "A small bowl of curd with soft, ripe orange segments, seeds and membrane removed, finely chopped", "nourishment_break_b": "Finely ground walnut mixed into a small bowl of warm milk, if walnut has already been introduced and tolerated", "dinner_a": "Rice with arhar dal and soft-cooked brinjal (baingan), finely mashed", "dinner_b": "Rice with arhar dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked brinjal (baingan), finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 5, "title": "The exception: when dairy, egg and animal-source food are very limited", "notes": "General reassurance doesn''t apply equally to every toddler. If your toddler''s diet includes very little dairy, egg or other animal-source food — whether from a vegan approach, a diagnosed milk allergy, lactose intolerance, or simply family preference — what matters most isn''t the label, but what''s actually replacing those foods. Appropriately chosen fortified foods and plant sources — a fortified plant milk (checked for its own fortification, since plant milks vary and aren''t automatically an equivalent swap for dairy), dal, whole grains, leafy greens, and nuts or seeds in safe forms — can meaningfully contribute to riboflavin intake when included regularly. Exactly how much they add up to depends on quantities and fortification levels this document can''t calculate for you, so a diet that''s substantially restricted — by choice, allergy or intolerance — is worth an individual review with your child''s healthcare team, ideally with a dietitian who can look at the whole pattern rather than one nutrient at a time. Riboflavin itself has no known interactions with medicines, and there''s no reason to avoid ordinary fortified foods.", "breakfast_a": "Dhokla (steamed besan cake), soft, finely chopped, served with plain curd", "breakfast_b": "Dhokla (steamed besan cake), soft, finely chopped, served with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft roti with chana dal and soft-cooked carrot (gajar), finely grated", "lunch_b": "Soft roti with chana dal, a fully cooked egg curry and soft-cooked carrot (gajar), finely grated", "nourishment_break_a": "A small bowl of curd with soft, ripe guava, deseeded and finely chopped", "nourishment_break_b": "Finely ground cashew mixed into a small bowl of plain curd, if cashew has already been introduced and tolerated", "dinner_a": "Rice with mixed dal and soft-cooked pumpkin, finely mashed", "dinner_b": "Rice with mixed dal, a fully cooked, lower-mercury fish curry, finely flaked and carefully checked for bones, and soft-cooked pumpkin, finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 6, "title": "What this week''s theme doesn''t mean", "notes": "A few things worth naming plainly: this doesn''t mean forcing milk on a toddler who dislikes it, buying a specialty supplement, or treating dal and dairy as boxes to tick at every meal. It doesn''t mean an occasional lighter day — a toddler who skips curd for a day, or eats mostly rice and dal for a stretch — is a problem. Riboflavin, like most of this series'' nutrients, rewards a pattern held loosely across weeks, not a perfect day. One small, harmless fact, in case you''re ever curious: riboflavin''s natural yellow colour is part of why urine can look a little brighter for a while after a multivitamin — nothing to worry about.", "breakfast_a": "Sattu paratha (roasted gram flour, mildly spiced), soft, served with plain curd", "breakfast_b": "Sattu paratha (roasted gram flour, mildly spiced), soft, served with a small portion of a tender, finely shredded mutton curry, fully cooked and free of bone fragments", "lunch_a": "Soft paratha with moong dal and soft-cooked capsicum, finely chopped", "lunch_b": "Soft paratha with moong dal, boneless, finely shredded chicken and soft-cooked capsicum, finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe watermelon, deseeded and finely chopped", "nourishment_break_b": "Finely ground sunflower seed mixed into a small bowl of warm milk, if sunflower seed has already been introduced and tolerated", "dinner_a": "Soft khichdi with chana dal and soft-cooked mushroom, finely chopped", "dinner_b": "Soft khichdi with chana dal, soft tofu, finely crumbled, and soft-cooked mushroom, finely chopped, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 7, "title": "Bringing it together", "notes": "If there''s one thing worth remembering from this week, it''s this: an ordinary varied diet — some dairy, egg or dal most days, plus the odd whole grain, green or nut — already covers your toddler''s riboflavin needs. The one exception worth genuine attention is a diet with very little dairy, egg or other animal-source food, where it''s worth making sure something reliable is filling that gap. Beyond that, there''s nothing to track, calculate or add specially this week.", "breakfast_a": "Appam (rice pancake), soft, served with a mild dal accompaniment", "breakfast_b": "Appam (rice pancake), soft, served with a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Rice with arhar dal and soft-cooked cabbage, finely shredded", "lunch_b": "Rice with arhar dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked cabbage, finely shredded", "nourishment_break_a": "A small bowl of curd with soft, ripe mango, peeled, deseeded and finely chopped", "nourishment_break_b": "Finely ground roasted chana (bhuna chana) mixed into a small bowl of plain curd", "dinner_a": "Soft roti with masoor dal and soft-cooked radish (mooli), finely chopped", "dinner_b": "Soft roti with masoor dal, a fully cooked egg curry and soft-cooked radish (mooli), finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food. One simple takeaway to carry forward: does your toddler''s week already include the everyday pattern — some dairy, egg or dal most days? If yes, you can let this one go. If not, pick one small, realistic addition rather than trying to change everything at once.", "still_hungry": null}]'::jsonb,
   'Notice, this week, whether cooking one shared meal for the whole table felt easier than expected — and whether you found yourself worrying about a single nutrient more than your toddler''s everyday eating pattern actually calls for. If something about your toddler''s growth or feeding is genuinely on your mind, that''s always worth raising with their healthcare team, regardless of this week''s theme.',
   'Next week brings a new focus for your family''s table. Until then, there''s nothing left to add from this week — just the ordinary rhythm of shared meals, continuing on.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
