  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 134: How much niacin (vitamin B3) does your toddler need, and where does it come from?
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   134,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'How much niacin (vitamin B3) does your toddler need, and where does it come from?',
   '"Niacin comes from many familiar foods, and the body can also make some from tryptophan in protein. A varied week containing pulses, nuts or seeds prepared safely, eggs, fish, meat or suitable fortified foods will usually provide what a toddler needs."',
   'Niacin (vitamin B3) helps your toddler''s body turn food into energy and keeps skin, gut and nervous system cells working properly. The body can also make niacin from tryptophan, an amino acid found in protein-rich foods. A varied diet with regular pulses, nuts or seeds, eggs, fish or meat is likely to provide enough for most healthy toddlers, without any special planning. Using this shared menu These meals are designed so the family can begin with the same basic food. Serve the mother a satisfying adult portion, including enough protein, vegetables and energy for her own needs. Adapt only the toddler''s portion to their chewing ability: remove bones and hard seeds, reduce salt and chilli, and cut or soften food as needed. A toddler does not need every family food mashed if they can already manage ordinary family textures safely.',
   'If you take prescription-dose niacin: continue it exactly as prescribed and follow the monitoring arranged by your healthcare team. Prescription doses can affect blood glucose and may require other safety monitoring. This concern does not apply to niacin naturally present in ordinary meals. If you manage diabetes, PCOS, high blood pressure, thyroid concerns or anaemia, keep following your prescribed plan, monitoring and medication timing as usual — nothing about this week''s theme changes that guidance. None of this needs to turn every meal into detective work. A clear diagnosis, from the right professional, is what actually tells you which foods or proportions are the concern. Your seven-day shared family menu Choose either option at each meal according to your family''s preferences, available ingredients and dietary pattern. A and B are alternatives; you do not need to prepare both. —————————————————————————————————————————————————————————————————————————————————————————————— This week''s menu doesn''t change specially for this topic — pulses, dairy or eggs, meat or fish, and nuts or seeds prepared safely are already the everyday building blocks of this series'' meals. Wash all produce thoroughly with reliably safe water, and cook ingredients fully. ——————————————————————————————————————————————————————————————————————————————————————————————',
   NULL,
   NULL,
   '[{"day_number": 1, "title": "What niacin actually does", "notes": "Niacin, also called vitamin B3, helps your toddler''s body turn food into usable energy and keeps skin, gut and nervous system cells working the way they should. It isn''t something you need to track or calculate — it''s simply one of the ordinary things a varied diet already provides.", "breakfast_a": "Vegetable idli with grated carrot mixed through, served with sambar", "breakfast_b": "Vegetable idli with grated carrot mixed through and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Vegetable pulao (rice cooked with carrot, green peas, softened and lightly squashed, and finely chopped mushroom, mildly spiced), served with plain curd", "lunch_b": "Vegetable pulao (rice cooked with carrot, green peas, softened and lightly squashed, and finely chopped mushroom, mildly spiced) with boneless, finely shredded chicken mixed through, served with plain curd", "nourishment_break_a": "A small bowl of curd with soft, ripe fig, stem removed and finely chopped", "nourishment_break_b": "Almond, ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if almond has already been introduced and tolerated", "dinner_a": "Soft roti with arhar dal and soft-cooked cauliflower, finely chopped", "dinner_b": "Soft roti with arhar dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked cauliflower, finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 2, "title": "How much, and an easy way to think about it", "notes": "The US NIH and WHO/FAO recommend 6 mg of niacin equivalents a day for children aged 1–3 years. ICMR-NIN''s 2020 Recommended Dietary Allowance for Indian children of this age is 8 mg niacin equivalents a day. A niacin equivalent includes both niacin obtained directly from food and niacin the body can make from tryptophan, an amino acid found in protein. One milligram of niacin equivalent is defined as 1 mg of niacin or 60 mg of tryptophan. Parents do not need to calculate either amount; a varied diet containing suitable protein foods and niacin sources is the practical focus.", "breakfast_a": "Besan (gram flour) chilla with finely grated onion and tomato mixed through, served with plain curd", "breakfast_b": "Besan (gram flour) chilla with finely grated onion and tomato mixed through and a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft khichdi with moong dal and thoroughly cooked spinach (palak), finely chopped", "lunch_b": "Soft khichdi with moong dal, soft tofu, finely crumbled, and thoroughly cooked spinach (palak), finely chopped, if soy has already been introduced and tolerated", "nourishment_break_a": "A small bowl of curd with soft, ripe jamun (Indian black plum), skin and seed removed, finely mashed", "nourishment_break_b": "Cashew, ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if cashew has already been introduced and tolerated", "dinner_a": "Soft paratha with masoor dal and soft-cooked pumpkin, finely mashed", "dinner_b": "Soft paratha with masoor dal, a fully cooked egg curry and soft-cooked pumpkin, finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 3, "title": "Does your toddler''s week already cover this?", "notes": "Here''s a simple way to check: does your toddler''s week already include some dal or other pulses, milk or curd, an egg, or meat, fish or poultry a few times, along with nuts or seeds prepared safely? If so, niacin is likely to be well covered. This week''s shared menu follows that same ordinary pattern, rather than adding anything new.", "breakfast_a": "Vegetable upma with grated carrot and green peas, softened and lightly squashed, mixed through, served with plain curd", "breakfast_b": "Vegetable upma with grated carrot and green peas, softened and lightly squashed, mixed through, served with a soft scrambled egg (bhurji), fully cooked, on the side", "lunch_a": "Curd rice (thayir sadam) with grated beetroot mixed through and a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler", "lunch_b": "Curd rice (thayir sadam) with grated beetroot mixed through, a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler, and boneless, finely shredded chicken mixed through", "nourishment_break_a": "A small bowl of curd with soft, seedless grapes, quartered lengthwise", "nourishment_break_b": "Walnut, ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if walnut has already been introduced and tolerated", "dinner_a": "Rice with chana dal and soft-cooked green beans, finely chopped", "dinner_b": "Rice with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked green beans, finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 4, "title": "Where niacin comes from", "notes": "Poultry, meat and fish are rich sources of readily available niacin. Peanuts, other nuts, pulses and some grains also contribute, while protein foods provide tryptophan that the body can convert to niacin. Fortified or enriched grain products may provide additional niacin, although fortification varies between products. Eggs and milk are valuable mainly for the tryptophan they provide, rather than as concentrated sources of niacin itself. Worth knowing: Adult niacin or vitamin B-complex supplements are dosed for adults, not toddlers, and shouldn''t be given without your pediatrician''s guidance. Niacin naturally present in ordinary foods does not carry this supplement-related toxicity concern. For you: Niacin needs are slightly higher while breastfeeding. The same varied pattern of pulses, dairy or eggs where included, meat or fish where included, nuts or seeds prepared safely, and fortified foods can contribute to your needs in adult portions. You do not need to calculate individual foods unless your healthcare team has advised you to monitor your diet for a specific reason.", "breakfast_a": "Jowar (sorghum) porridge with grated apple, cooked until soft in the porridge, served with milk", "breakfast_b": "Jowar (sorghum) porridge with grated apple, cooked until soft in the porridge, and a small portion of mild, fully cooked minced mutton, finely crumbled", "lunch_a": "Vegetable daliya (broken wheat, mildly spiced) with carrot, green peas, softened and lightly squashed, and finely chopped mushroom folded through", "lunch_b": "Vegetable daliya (broken wheat, mildly spiced) with carrot, green peas, softened and lightly squashed, and finely chopped mushroom folded through, and a fully cooked, lower-mercury fish curry, finely flaked and carefully checked for bones, mixed in", "nourishment_break_a": "A small bowl of curd with soft, ripe plum, peeled, deseeded and finely chopped", "nourishment_break_b": "White sesame (safed til), ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if sesame has already been introduced and tolerated", "dinner_a": "Rice with rajma (kidney bean curry) and soft-cooked bottle gourd (lauki), finely mashed", "dinner_b": "Rice with rajma (kidney bean curry), a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked bottle gourd (lauki), finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 5, "title": "If your toddler eats a vegetarian diet", "notes": "Vegetarian toddlers can meet their niacin needs through a varied diet. Useful contributors include pulses, peanuts and other nuts prepared safely, seeds, mushrooms, whole grains and appropriately fortified foods. Milk, curd, paneer and eggs, when included in the family''s diet, provide protein and tryptophan that contribute to niacin equivalents. No single food needs to supply the full amount. Offer peanuts only as smooth peanut butter spread thinly, smooth chutney, or a finely ground powder mixed thoroughly into food — never as whole or chopped roasted peanuts for a toddler.", "breakfast_a": "Moong dal chilla with grated carrot mixed through, served with plain curd", "breakfast_b": "Moong dal chilla with grated carrot mixed through and a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Soft roti with moong dal and soft-cooked radish (mooli), finely chopped", "lunch_b": "Soft roti with moong dal, boneless, finely shredded chicken and soft-cooked radish (mooli), finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe lychee, peeled and pit removed, mashed or cut into very small flattened pieces appropriate to the toddler''s chewing skills", "nourishment_break_b": "Pistachio, ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if pistachio has already been introduced and tolerated", "dinner_a": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped capsicum, mildly spiced), served with plain curd", "dinner_b": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped capsicum, mildly spiced) with soft tofu, finely crumbled, mixed through, served with plain curd, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 6, "title": "What this week''s theme doesn''t mean", "notes": "Niacin deficiency is uncommon in people eating a varied diet. Risk is more relevant with severe or prolonged undernutrition, a very restricted diet, significant malabsorption, or certain uncommon medical conditions affecting tryptophan or niacin metabolism. These situations require healthcare assessment rather than adding a niacin supplement independently. Ordinary foods do not cause niacin toxicity, but concentrated supplements and prescription-dose niacin can cause adverse effects.", "breakfast_a": "Ragi (finger millet) porridge with grated pear, cooked until soft in the porridge, served with milk", "breakfast_b": "Ragi (finger millet) porridge with grated pear, cooked until soft in the porridge, and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Rice with masoor dal and soft-cooked ridge gourd (turai), finely chopped", "lunch_b": "Rice with masoor dal, a fully cooked egg curry and soft-cooked ridge gourd (turai), finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe muskmelon (kharbooja), deseeded and finely chopped", "nourishment_break_b": "Flaxseed (alsi), ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if flaxseed has already been introduced and tolerated", "dinner_a": "A warm mixed vegetable soup (carrot, mushroom, tomato and green beans, finely chopped), lightly blended, with soft rice on the side", "dinner_b": "A warm mixed vegetable soup (carrot, mushroom, tomato and green beans, finely chopped), lightly blended, with a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones, and soft rice on the side If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 7, "title": "Bringing it together", "notes": "This week''s shared menu draws on the same dal, milk, egg, meat, fish, nuts and seeds your family already eats regularly. Between direct niacin in these foods and what the body makes from tryptophan, a varied diet like this is likely to provide enough for most healthy toddlers — without any specific food needing to carry the whole job.", "breakfast_a": "Rava (semolina) uttapam with grated carrot mixed through, served with a mild dal accompaniment", "breakfast_b": "Rava (semolina) uttapam with grated carrot mixed through and a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft khichdi with chana dal and soft-cooked carrot (gajar), finely grated", "lunch_b": "Soft khichdi with chana dal and soft-cooked carrot (gajar), finely grated, and a fully cooked hard-boiled egg, finely chopped, on the side", "nourishment_break_a": "A small bowl of curd with soft, ripe strawberry, hulled and finely chopped", "nourishment_break_b": "Chironji (charoli), ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if chironji has already been introduced and tolerated", "dinner_a": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and thoroughly cooked drumstick, with the soft pulp scraped from the fibrous pod and finely mashed, mildly spiced), served with plain curd", "dinner_b": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and thoroughly cooked drumstick, with the soft pulp scraped from the fibrous pod and finely mashed, mildly spiced) with soft tofu, finely crumbled, mixed through, served with plain curd, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food. Think back over your toddler''s last few meals: was there dal, milk, egg, meat, fish or a safely prepared nut or seed somewhere in the mix? If so, this week''s nutrient is likely well covered already.", "still_hungry": null}]'::jsonb,
   'Notice this week whether thinking about a specific nutrient changed how you looked at an ordinary meal, or whether it mostly confirmed what your family already eats. Both are useful things to know about how you want to use this series going forward.',
   'Next week brings a new focus for your family''s table. Until then, this week doesn''t ask for anything more than the meals already on your plate.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 135: What your toddler learns about food just by watching you eat
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   135,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'What your toddler learns about food just by watching you eat',
   '"Toddlers learn about food by watching the people they trust eat. Calm modelling can often communicate more effectively than repeated persuasion."',
   'Toddlers learn about food partly by watching the trusted adults around them eat. Research links parental modelling and parents'' own food patterns with children''s diet quality. Calm exposure may help, while pressure to eat can sometimes make food acceptance harder. Using this shared menu These meals are designed so the family can begin with the same basic food. Serve the mother a satisfying adult portion, including enough protein, vegetables and energy for her own needs. Adapt only the toddler''s portion to their chewing ability: remove bones and hard seeds, reduce salt and chilli, and cut or soften food as needed. A toddler does not need every family food mashed if they can already manage ordinary family textures safely.',
   'If a health condition (such as diabetes, PCOS, or a prescribed diet) shapes what you eat: modeling still works within your own restrictions — your toddler benefits from seeing you eat calmly and regularly, not from which specific foods happen to be on your plate. If you manage diabetes, PCOS, high blood pressure, thyroid concerns or anaemia, keep following your prescribed plan, monitoring and medication timing as usual — nothing about this week''s theme changes that guidance. None of this needs to change how you already manage your own health. Your prescribed plan comes first; this week''s habit is simply something your toddler picks up along the way, not an additional thing to manage. Your seven-day shared family menu Choose either option at each meal according to your family''s preferences, available ingredients and dietary pattern. A and B are alternatives; you do not need to prepare both. ——————————————————————————————————————————————————————————————————————————————————————————– This week''s menu doesn''t change specially for this topic — the same shared family meal works just as well, as long as some of what''s on your toddler''s plate is also visibly on yours. Wash all produce thoroughly with reliably safe water, and cook ingredients fully. ——————————————————————————————————————————————————————————————————————————————————————————–',
   NULL,
   NULL,
   '[{"day_number": 1, "title": "What your toddler is learning just by watching you eat", "notes": "Toddlers learn a lot about food by watching the people they trust eat, not only from what''s explained to them. Research links parental modelling — regularly eating a food yourself, without necessarily saying anything about it — with a child''s own diet quality, even after accounting for how healthy the parent''s diet already is. You don''t need to eat flawlessly for this to help; simply letting your toddler see you eat the food sometimes, calmly and without commentary, appears to be part of what makes a difference.", "breakfast_a": "Missi roti, soft, served with a mild dal accompaniment", "breakfast_b": "Missi roti, soft, served with a small portion of mild, fully cooked minced mutton, finely crumbled", "lunch_a": "Vegetable pulao (rice cooked with carrot, green peas, softened and lightly squashed, and finely chopped cauliflower, mildly spiced), served with plain curd", "lunch_b": "Vegetable pulao (rice cooked with carrot, green peas, softened and lightly squashed, and finely chopped cauliflower, mildly spiced) with boneless, finely shredded chicken mixed through, served with plain curd", "nourishment_break_a": "A small bowl of curd with soft, ripe mango, peeled, deseeded and finely chopped", "nourishment_break_b": "Almond, ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if almond has already been introduced and tolerated", "dinner_a": "Soft roti with arhar dal and soft-cooked knolkhol (ganth gobi), finely chopped", "dinner_b": "Soft roti with arhar dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked knolkhol (ganth gobi), finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 2, "title": "Why modelling can work better than pressure", "notes": "Pressure and modelling are not the same thing. In one experiment, preschool children repeatedly asked to finish a soup ate less of it and made more negative comments than when the soup was offered without pressure. This does not mean that every warm or encouraging comment is harmful. The useful distinction is between offering support and repeatedly pushing a child to eat.", "breakfast_a": "Sattu paratha (roasted gram flour, mildly spiced), torn into manageable pieces and softened with curd or dal as needed, served with plain curd", "breakfast_b": "Sattu paratha (roasted gram flour, mildly spiced), torn into manageable pieces and softened with curd or dal as needed, served with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft khichdi with moong dal and soft-cooked bottle gourd (lauki), finely mashed", "lunch_b": "Soft khichdi with moong dal, soft tofu, finely crumbled, and soft-cooked bottle gourd (lauki), finely mashed, if soy has already been introduced and tolerated", "nourishment_break_a": "A small bowl of curd with soft, ripe banana, mashed", "nourishment_break_b": "Cashew, ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if cashew has already been introduced and tolerated", "dinner_a": "Soft paratha with masoor dal and soft-cooked carrot (gajar), finely grated", "dinner_b": "Soft paratha with masoor dal, a fully cooked egg curry and soft-cooked carrot (gajar), finely grated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 3, "title": "A simple pattern check", "notes": "A simple way to check this in your own week: is there a food you''d like your toddler to eat more of that you also eat, visibly, in front of them? If a food only ever appears on your toddler''s plate and never on yours, it may be worth occasionally putting some on your own plate too — not as a rule, just as something worth noticing.", "breakfast_a": "Appam (rice pancake), soft, served with a mild dal accompaniment", "breakfast_b": "Appam (rice pancake), soft, served with a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Curd rice (thayir sadam) with grated capsicum mixed through and a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler", "lunch_b": "Curd rice (thayir sadam) with grated capsicum mixed through, a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler, and boneless, finely shredded chicken mixed through", "nourishment_break_a": "A small bowl of curd with soft, ripe papaya, deseeded and finely mashed", "nourishment_break_b": "Walnut, ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if walnut has already been introduced and tolerated", "dinner_a": "Rice with chana dal and soft-cooked tomato, finely mashed", "dinner_b": "Rice with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked tomato, finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 4, "title": "Shared eating does not have to be perfect", "notes": "When possible, letting your toddler occasionally see you eating some of the same foods can provide a useful example. You do not need every meal to happen at exactly the same time, and missing shared meals does not mean you have lost an opportunity. Modelling can happen across many ordinary family moments. For you: If you often eat after serving everyone else, you have not done anything wrong. When it feels practical, sitting for a few bites or joining another family meal can let your toddler see you eat — but this is an option, not another demand on you.", "breakfast_a": "Dhokla (steamed besan cake), soft, finely chopped, served with plain curd", "breakfast_b": "Dhokla (steamed besan cake), soft, finely chopped, served with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Vegetable daliya (broken wheat, mildly spiced) with spinach (palak) and cauliflower folded through", "lunch_b": "Vegetable daliya (broken wheat, mildly spiced) with spinach (palak) and cauliflower folded through, and a fully cooked, lower-mercury fish curry, finely flaked and carefully checked for bones, mixed in", "nourishment_break_a": "A small bowl of curd with soft, ripe orange segments, seeds and membrane removed, finely chopped", "nourishment_break_b": "White sesame (safed til), ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if sesame has already been introduced and tolerated", "dinner_a": "Rice with rajma (kidney bean curry) and soft-cooked cabbage, finely shredded", "dinner_b": "Rice with rajma (kidney bean curry), a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked cabbage, finely shredded If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 5, "title": "It''s not only about you", "notes": "This isn''t only about you. Toddlers also learn from watching an older sibling try a food, or seeing their father or grandparent eat something with evident enjoyment. If your toddler has an older sibling who eats a wider variety, that''s genuinely doing some of this work already — you don''t have to be the only person at the table demonstrating this.", "breakfast_a": "Idli (soft), served with sambar", "breakfast_b": "Idli (soft), served with a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Soft roti with moong dal and soft-cooked green beans, finely chopped", "lunch_b": "Soft roti with moong dal, boneless, finely shredded chicken and soft-cooked green beans, finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe guava, peeled and deseeded, finely grated or cooked until soft", "nourishment_break_b": "Pistachio, ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if pistachio has already been introduced and tolerated", "dinner_a": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped beetroot, mildly spiced), served with plain curd", "dinner_b": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped beetroot, mildly spiced) with soft tofu, finely crumbled, mixed through, served with plain curd, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 6, "title": "What this doesn''t mean", "notes": "This is not a guarantee. Toddlers differ naturally in food responsiveness, sensitivity and willingness to try unfamiliar foods. Research suggests that inherited differences contribute substantially to food fussiness, while experiences and the home environment can still matter — particularly during toddlerhood. If you eat well and openly in front of your toddler and they''re still a cautious eater, that isn''t a sign you''ve done something wrong — it''s exactly what you''d expect for a good number of toddlers, regardless of what their parents model.", "breakfast_a": "Wheat dalia (broken wheat) porridge with grated mango, cooked until soft in the porridge, served with milk", "breakfast_b": "Wheat dalia (broken wheat) porridge with grated mango, cooked until soft in the porridge, and a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Soft khichdi with masoor dal and soft-cooked green beans, finely chopped", "lunch_b": "Soft khichdi with masoor dal, a fully cooked egg curry and soft-cooked green beans, finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe watermelon, deseeded and finely chopped", "nourishment_break_b": "Flaxseed (alsi), ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if flaxseed has already been introduced and tolerated", "dinner_a": "A warm mixed vegetable soup (carrot, spinach, tomato and pumpkin), lightly blended, with soft rice on the side", "dinner_b": "A warm mixed vegetable soup (carrot, spinach, tomato and pumpkin), lightly blended, with a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones, and soft rice on the side If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 7, "title": "Bringing it together", "notes": "Between eating in front of your toddler without pressuring them, and letting other family members share in that too, this week''s habit doesn''t ask you to change your menu or your schedule — just to notice how much your toddler is already watching, and let that work quietly in the background.", "breakfast_a": "Semiya (vermicelli) upma with grated carrot mixed through, served with plain curd", "breakfast_b": "Semiya (vermicelli) upma with grated carrot mixed through and a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft khichdi with chana dal and soft-cooked capsicum, finely chopped", "lunch_b": "Soft khichdi with chana dal and soft-cooked capsicum, finely chopped, and a fully cooked hard-boiled egg, finely chopped, on the side", "nourishment_break_a": "A small bowl of curd with soft, ripe apricot, peeled, deseeded and finely chopped", "nourishment_break_b": "Chironji (charoli), ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if chironji has already been introduced and tolerated", "dinner_a": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely grated radish (mooli), cooked until soft, mildly spiced), served with plain curd", "dinner_b": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely grated radish (mooli), cooked until soft, mildly spiced) with soft tofu, finely crumbled, mixed through, served with plain curd, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food. Think about your last few family meals: was there a food on your plate that you''d like your toddler to eat more of? If a food shows up on your plate too sometimes, it''s doing some of this week''s work without you needing to add anything.", "still_hungry": null}]'::jsonb,
   'Notice this week whether eating in front of your toddler, without saying anything about it, feels different from encouraging them to eat. Both are useful things to notice about how your family''s mealtimes already work.',
   'Next week brings a new focus for your family''s table. Until then, this week doesn''t ask for anything more than the meals already on your plate.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
