  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 136: How much pantothenic acid (vitamin B5) does your toddler need, and where does it come from?
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   136,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'How much pantothenic acid (vitamin B5) does your toddler need, and where does it come from?',
   '"Pantothenic acid is found in such a wide range of ordinary foods that its name literally means ''from everywhere.'' A varied week of meals is likely to cover it well, without any special planning."',
   'Pantothenic acid (vitamin B5) helps your toddler''s body turn food into usable energy and supports the production of certain fats and hormones. It''s found across dal, dairy, eggs, whole grains, mushrooms and many vegetables, which is part of why true deficiency is rare in people eating a normal diet. A varied week of family meals is likely to provide enough for most healthy toddlers, without any special planning. Using this shared menu These meals are designed so the family can begin with the same basic food. Serve the mother a satisfying adult portion, including enough protein, vegetables and energy for her own needs. Adapt only the toddler''s portion to their chewing ability: remove bones and hard seeds, reduce salt and chilli, and cut or soften food as needed. A toddler does not need every family food mashed if they can already manage ordinary family textures safely.',
   'This week''s nutrient: Pantothenic acid naturally present in ordinary foods is not known to require special dietary adjustment for diabetes, PCOS, high blood pressure, thyroid conditions or anaemia. Pantothenic acid is not known to have clinically relevant medication interactions, but prescribed treatment and supplement advice should continue unchanged. If you manage one of these conditions, keep following your prescribed eating plan, monitoring and medication timing as usual. Nothing about this week''s theme replaces that guidance. Your seven-day shared family menu Choose either option at each meal according to your family''s preferences, available ingredients and dietary pattern. A and B are alternatives; you do not need to prepare both. ——————————————————————————————————————————————————————————————————————————————————————————————————– This week''s menu doesn''t change specially for this topic — dal, dairy, eggs, whole grains and vegetables like mushroom, cauliflower or broccoli are already the everyday building blocks of this series'' meals. Wash all produce thoroughly with reliably safe water, and cook ingredients fully. ——————————————————————————————————————————————————————————————————————————————————————————————————–',
   NULL,
   NULL,
   '[{"day_number": 1, "title": "What pantothenic acid actually does", "notes": "Pantothenic acid, also called vitamin B5, helps your toddler''s body build a compound involved in turning the carbohydrate, fat and protein in food into usable energy, and in making certain fats and hormones. Its name comes from a Greek word meaning ''from everywhere'' — a hint at how widely it''s found in ordinary food, and how little most families ever need to think about it.", "breakfast_a": "Oats porridge with grated apple, cooked until soft in the porridge, served with milk", "breakfast_b": "Oats porridge with grated apple, cooked until soft in the porridge, and a small portion of mild, fully cooked minced mutton, finely crumbled", "lunch_a": "Soft khichdi with chana dal and soft-cooked cauliflower, finely chopped", "lunch_b": "Soft khichdi with chana dal, boneless, finely shredded chicken and soft-cooked cauliflower, finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe pear, peeled, cored and finely chopped", "nourishment_break_b": "Peanut, ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if peanut has already been introduced and tolerated", "dinner_a": "Soft roti with arhar dal and soft-cooked capsicum, finely chopped", "dinner_b": "Soft roti with arhar dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked capsicum, finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 2, "title": "How much, and where the numbers come from", "notes": "The US NIH and WHO/FAO use an intake figure of 2 milligrams a day for children aged 1–3 years. This is an Adequate Intake estimate rather than a precisely established requirement because available evidence is not sufficient to calculate an average requirement. Parents do not need to calculate or track a daily total.", "breakfast_a": "Paneer paratha, soft, served with plain curd", "breakfast_b": "Paneer paratha, soft, served with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped broccoli, mildly spiced), served with plain curd", "lunch_b": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped broccoli, mildly spiced) with soft tofu, finely crumbled, mixed through, served with plain curd, if soy has already been introduced and tolerated", "nourishment_break_a": "A small bowl of curd with soft, ripe kiwi, peeled and finely chopped", "nourishment_break_b": "Sunflower seeds, ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if sunflower seeds have already been introduced and tolerated", "dinner_a": "Soft roti, torn into manageable pieces and softened with moong dal, with soft-cooked bottle gourd (lauki), finely mashed", "dinner_b": "Soft roti, torn into manageable pieces and softened with moong dal, with soft-cooked bottle gourd (lauki), finely mashed, and a fully cooked egg curry If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 3, "title": "Does your toddler''s week already cover this?", "notes": "Here''s a simple way to check: does your toddler''s week already include some dal or other legumes, milk, curd or paneer, an egg, whole grains such as wheat or oats, and a vegetable or two such as cauliflower, broccoli or mushroom? If so, this pattern is likely to provide pantothenic acid from several sources — this is one of the least commonly deficient vitamins in any typical diet, vegetarian or not.", "breakfast_a": "Vegetable poha (flattened rice) with roasted peanut, ground finely, and turmeric mixed through, served with plain curd, if peanut has already been introduced and tolerated", "breakfast_b": "Vegetable poha (flattened rice) with roasted peanut, ground finely, and turmeric mixed through, and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones, if peanut has already been introduced and tolerated", "lunch_a": "Soft khichdi with moong dal and soft-cooked green beans, finely chopped", "lunch_b": "Soft khichdi with moong dal, boneless, finely shredded chicken and soft-cooked green beans, finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe pineapple, peeled, core removed and finely chopped", "nourishment_break_b": "Pumpkin seed, ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if pumpkin seed has already been introduced and tolerated", "dinner_a": "Soft paratha with chana dal and soft-cooked beetroot, finely grated", "dinner_b": "Soft paratha with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked beetroot, finely grated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 4, "title": "Where pantothenic acid comes from", "notes": "Pantothenic acid is found in a very wide range of everyday foods: eggs, milk, curd and other dairy, meat, fish, whole grains, legumes, mushrooms, and vegetables such as broccoli, cauliflower and sweet potato. Heavy processing and refining can reduce a food''s pantothenic acid content, so including a mix of freshly cooked foods alongside packaged or refined ones is a reasonable, ordinary habit rather than a rule to follow strictly.", "breakfast_a": "Vegetable stuffed paratha (grated carrot and cabbage), soft, served with plain curd", "breakfast_b": "Vegetable stuffed paratha (grated carrot and cabbage), soft, served with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Curd rice (thayir sadam) with grated carrot mixed through and a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler", "lunch_b": "Curd rice (thayir sadam) with grated carrot mixed through, a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler, and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "nourishment_break_a": "A small bowl of curd with soft, ripe pomegranate arils crushed and pressed through a sieve to remove the hard seed pieces", "nourishment_break_b": "Black sesame (kala til), ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if sesame has already been introduced and tolerated", "dinner_a": "A warm mixed vegetable soup (carrot, broccoli, tomato and sweet potato, finely chopped), lightly blended, with soft rice on the side", "dinner_b": "A warm mixed vegetable soup (carrot, broccoli, tomato and sweet potato, finely chopped), lightly blended, with soft tofu, finely crumbled, and soft rice on the side, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 5, "title": "If your toddler eats a vegetarian diet", "notes": "Vegetarian toddlers can obtain pantothenic acid from a varied diet. Milk, curd, paneer, eggs where included, legumes, whole grains and mushrooms are all useful contributors, and this vitamin is widely enough distributed across plant and dairy foods that no special combination or planning is needed for a vegetarian diet.", "breakfast_a": "Mixed dal cheela with grated bottle gourd mixed through, served with plain curd", "breakfast_b": "Mixed dal cheela with grated bottle gourd mixed through and a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Rice with rajma (kidney bean curry) and mashed sweet potato", "lunch_b": "Rice with rajma (kidney bean curry), boneless, finely shredded chicken and mashed sweet potato", "nourishment_break_a": "A small bowl of curd with soft, ripe custard apple (sitaphal), deseeded and finely mashed", "nourishment_break_b": "Chia seed, soaked until softened and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if chia seed has already been introduced and tolerated", "dinner_a": "Rice with masoor dal and soft-cooked knolkhol (ganth gobi), finely chopped", "dinner_b": "Rice with masoor dal, soft tofu, finely crumbled, and soft-cooked knolkhol (ganth gobi), finely chopped, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 6, "title": "What this week''s theme doesn''t mean", "notes": "Pantothenic acid deficiency is rare because the vitamin is present in many foods. Reported deficiency has generally occurred alongside severe malnutrition or in research involving diets containing virtually no pantothenic acid or a substance that interfered with its metabolism. Pantothenic acid is also sold in supplements, but a healthy toddler should not be given a vitamin supplement unless their healthcare professional has recommended it.", "breakfast_a": "Broken wheat upma (daliya upma) with mushroom and green peas, softened and lightly squashed, mixed through, served with plain curd", "breakfast_b": "Broken wheat upma (daliya upma) with mushroom and green peas, softened and lightly squashed, mixed through, and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Vegetable daliya (broken wheat, mildly spiced) with mashed pumpkin folded through", "lunch_b": "Vegetable daliya (broken wheat, mildly spiced) with mashed pumpkin folded through, and a tender, finely shredded mutton curry, fully cooked and free of bone fragments, mixed in", "nourishment_break_a": "A small bowl of curd with soft, ripe chikoo (sapota), peeled, deseeded and finely mashed", "nourishment_break_b": "Magaz (melon seeds), ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if magaz has already been introduced and tolerated", "dinner_a": "Curd rice (thayir sadam) with grated cauliflower mixed through and a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler", "dinner_b": "Curd rice (thayir sadam) with grated cauliflower mixed through, a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler, and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 7, "title": "Bringing it together", "notes": "This week''s shared menu draws on the same dal, milk, egg, whole grain, mushroom and vegetable variety your family already eats regularly. Pantothenic acid is one of the more quietly reliable nutrients in this series — spread across so many ordinary foods that a typical varied diet, vegetarian or not, is likely to provide what a toddler needs without any specific food needing to carry the job.", "breakfast_a": "Multigrain paratha (whole wheat and oats), soft, with grated radish, cooked until soft, mixed through, served with plain curd", "breakfast_b": "Multigrain paratha (whole wheat and oats), soft, with grated radish, cooked until soft, mixed through, served with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft khichdi with masoor dal and thoroughly cooked spinach (palak), finely chopped", "lunch_b": "Soft khichdi with masoor dal, a fully cooked egg curry and thoroughly cooked spinach (palak), finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe mulberry (shahtoot), washed and finely mashed", "nourishment_break_b": "Makhana (fox nut), roasted and ground to a fine powder, mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if makhana has already been introduced and tolerated", "dinner_a": "Rice with moong dal and thoroughly cooked drumstick, with the soft pulp scraped from the fibrous pod and finely mashed", "dinner_b": "Rice with moong dal and thoroughly cooked drumstick, with the soft pulp scraped from the fibrous pod and finely mashed, and a fully cooked hard-boiled egg, finely chopped, on the side If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food. Think back over your toddler''s last few meals: was there dal, milk, egg, whole grain or a vegetable like cauliflower, broccoli or mushroom somewhere in the mix? If so, this week''s nutrient is likely well covered already.", "still_hungry": null}]'::jsonb,
   'Notice this week whether thinking about a specific nutrient changed how you looked at an ordinary meal, or whether it mostly confirmed what your family already eats. Both are useful things to know about how you want to use this series going forward.',
   'Next week brings a new focus for your family''s table. Until then, this week doesn''t ask for anything more than the meals already on your plate.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 137: How your toddler's spoon and fork skills are developing, and how much mess is still normal
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   137,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'How your toddler''s spoon and fork skills are developing, and how much mess is still normal',
   '"There''s no single ''correct'' way to hold a spoon at this age. Most toddlers are still developing utensil skills that keep improving for years, and eating with hands remains a genuine skill in its own right — not something to rush past."',
   'Somewhere between two and three years old, most toddlers are refining how they use a spoon and starting to explore a fork, with real variation in pace from one child to the next. Mess at this age is genuinely normal, not a sign anything is off, and eating with clean hands is a real skill of its own — not a stage to move past quickly. This week looks at what''s actually changing, how much variation is ordinary, and where it''s worth a conversation with your pediatrician. Using this shared menu These meals are designed so the family can begin with the same basic food. Serve the mother a satisfying adult portion, including enough protein, vegetables and energy for her own needs. Adapt only the toddler''s portion to their chewing ability: remove bones and hard seeds, reduce salt and chilli, and cut or soften food as needed. A toddler does not need every family food mashed if they can already manage ordinary family textures safely.',
   'If your toddler has a diagnosed motor delay, feeding therapy plan, or sensory processing concern affecting self-feeding: follow the pacing and goals set by your child''s therapy or medical team — this week''s general timeline is written for typically developing toddlers and may not apply the same way. If you manage diabetes, PCOS, high blood pressure, thyroid concerns or anaemia, keep following your prescribed plan, monitoring and medication timing as usual — nothing about this week''s theme changes that guidance. None of this needs to become something you formally track or drill. Ordinary, low-pressure opportunities at meals provide plenty of practice. An unhurried, years-long process is exactly what''s expected at this age. Your seven-day shared family menu Choose either option at each meal according to your family''s preferences, available ingredients and dietary pattern. A and B are alternatives; you do not need to prepare both. ————————————————————————————————————————————————————————————————————————————————————————————- This week''s menu doesn''t change specially for this topic — continue offering the same family foods with a spoon, fork and clean hands available, and let your toddler choose how to eat them. Wash all produce thoroughly with reliably safe water, and cook ingredients fully. ————————————————————————————————————————————————————————————————————————————————————————————-',
   NULL,
   NULL,
   '[{"day_number": 1, "title": "What''s actually changing right now", "notes": "Utensil skills develop gradually. The CDC lists eating with a spoon as a milestone most children can manage by age two, while fork use commonly becomes more functional closer to age three. A toddler between these ages may still spill food, switch between utensils and fingers, or need occasional help. The milestone concerns functional self-feeding — not one correct grip or neat technique.", "breakfast_a": "Rava idli (soft), served with sambar", "breakfast_b": "Rava idli (soft), served with sambar and a small portion of mild, fully cooked minced mutton, finely crumbled", "lunch_a": "Soft khichdi with arhar dal and soft-cooked ridge gourd (turai), finely chopped", "lunch_b": "Soft khichdi with arhar dal, boneless, finely shredded chicken and soft-cooked ridge gourd (turai), finely chopped", "nourishment_break_a": "A small bowl of curd with soft, ripe fig, stem removed and finely chopped", "nourishment_break_b": "Pine nut (chilgoza), ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if pine nut has already been introduced and tolerated", "dinner_a": "Soft roti with chana dal and soft-cooked tinda (apple gourd), finely mashed", "dinner_b": "Soft roti with chana dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked tinda (apple gourd), finely mashed If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 2, "title": "How much mess is genuinely normal", "notes": "Mess can remain common while utensil control improves. Spilling some food, missing the mouth occasionally or switching back to fingers can all occur during normal skill development. The practical focus is whether the toddler is gradually becoming more able to feed themselves — not whether the table stays clean.", "breakfast_a": "Moong dal dosa, soft, served with plain curd", "breakfast_b": "Moong dal dosa, soft, served with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped parwal (pointed gourd), mildly spiced), served with plain curd", "lunch_b": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped parwal (pointed gourd), mildly spiced) with soft tofu, finely crumbled, mixed through, served with plain curd, if soy has already been introduced and tolerated", "nourishment_break_a": "A small bowl of curd with soft, ripe strawberry, hulled and finely chopped", "nourishment_break_b": "Poppy seed (khuskhus), ground to a smooth paste and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if poppy seed has already been introduced and tolerated", "dinner_a": "Curd rice (thayir sadam) with soft-cooked French beans, finely chopped, mixed through and a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler", "dinner_b": "Curd rice (thayir sadam) with soft-cooked French beans, finely chopped, mixed through, a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler, and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 3, "title": "A simple pattern check", "notes": "Notice what your toddler can do rather than how neatly they do it. Can they use a spoon to get at least some food to their mouth independently? Are their attempts gradually becoming easier? Fork use may still be emerging. If spoon use remains very difficult, progress has stopped, or you have any concern about their broader development, mention it to their healthcare professional.", "breakfast_a": "Methi (fenugreek greens) paratha, soft, served with plain curd", "breakfast_b": "Methi (fenugreek greens) paratha, soft, served with a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Soft khichdi with moong dal and soft-cooked tomato, finely mashed", "lunch_b": "Soft khichdi with moong dal, boneless, finely shredded chicken and soft-cooked tomato, finely mashed", "nourishment_break_a": "A small bowl of curd with soft, ripe apple, peeled, cored and finely grated", "nourishment_break_b": "Fresh coconut ground into a smooth paste and mixed thoroughly into a small bowl of warm milk, if coconut has already been introduced and tolerated", "dinner_a": "Soft paratha with masoor dal and okra (bhindi), thoroughly cooked until soft and finely chopped", "dinner_b": "Soft paratha with masoor dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and okra (bhindi), thoroughly cooked until soft and finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 4, "title": "When it''s worth a conversation with your pediatrician", "notes": "Because eating with a spoon is a milestone most children can manage by age two, it is reasonable to mention persistent difficulty with functional spoon use at a routine healthcare visit. Seek advice sooner if your toddler has lost a skill they previously had, or if utensil difficulty occurs with coughing or choking, difficulty chewing ordinary textures, food pocketing, very prolonged meals, poor growth, a highly restricted diet, or concerns about movement, communication or coordination. Worth knowing: Always have your toddler seated while eating, and never let them walk, run or play with food or a utensil in their mouth. Use child-sized, unbreakable utensils and check them regularly for worn, sharp or loose parts.", "breakfast_a": "Soft idiyappam (steamed rice noodles) with a mild dal and vegetable accompaniment (grated carrot and green peas, softened and lightly squashed)", "breakfast_b": "Soft idiyappam (steamed rice noodles) with a mild dal and vegetable accompaniment (grated carrot and green peas, softened and lightly squashed) and a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Vegetable daliya (broken wheat, mildly spiced) with green peas, softened and lightly squashed, and grated carrot folded through", "lunch_b": "Vegetable daliya (broken wheat, mildly spiced) with green peas, softened and lightly squashed, and grated carrot folded through, and a fully cooked egg curry mixed in", "nourishment_break_a": "A small bowl of curd with soft, ripe plum, peeled, deseeded and finely chopped", "nourishment_break_b": "Roasted chana (bhuna chana), ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if chana has already been introduced and tolerated", "dinner_a": "A warm mixed vegetable soup (ridge gourd, tomato, carrot and green peas, finely chopped), lightly blended, with soft rice on the side", "dinner_b": "A warm mixed vegetable soup (ridge gourd, tomato, carrot and green peas, finely chopped), lightly blended, with soft tofu, finely crumbled, and soft rice on the side, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 5, "title": "Eating with hands is a real skill too", "notes": "Eating with clean hands is a genuine, valuable skill in its own right, not a stage your toddler needs to be moved past. Scooping, pinching and bringing food to the mouth by hand takes real coordination, and in many households, including many Indian ones, it remains a normal, hygienic way to eat well into adulthood. Offering a spoon or fork alongside food, without insisting on it, lets your toddler build both kinds of skill at their own pace.", "breakfast_a": "Besan (gram flour) cheela with grated carrot mixed through, served with plain curd", "breakfast_b": "Besan (gram flour) cheela with grated carrot mixed through and a small portion of mild, fully cooked chicken keema, finely crumbled", "lunch_a": "Rice with rajma (kidney bean curry) and soft-cooked tinda (apple gourd), finely mashed", "lunch_b": "Rice with rajma (kidney bean curry), boneless, finely shredded chicken and soft-cooked tinda (apple gourd), finely mashed", "nourishment_break_a": "A small bowl of curd with soft, ripe muskmelon (kharbooja), deseeded and finely chopped", "nourishment_break_b": "Hazelnut, ground to a smooth powder and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if hazelnut has already been introduced and tolerated", "dinner_a": "Soft khichdi with masoor dal and soft-cooked parwal (pointed gourd), finely chopped", "dinner_b": "Soft khichdi with masoor dal, a tender, finely shredded mutton curry, fully cooked and free of bone fragments, and soft-cooked parwal (pointed gourd), finely chopped If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 6, "title": "What this week''s theme doesn''t mean", "notes": "This is not about correcting exactly how your toddler holds a spoon or rushing them onto a fork before they are ready. Different grips can still be functional. Offer child-sized utensils and foods that are easy to scoop or spear, then allow repeated, low-pressure opportunities to use them. There is no need for drills or for introducing a table knife this week.", "breakfast_a": "Suji (rava) uttapam with grated capsicum mixed through, served with a mild dal accompaniment", "breakfast_b": "Suji (rava) uttapam with grated capsicum mixed through and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "lunch_a": "Curd rice (thayir sadam) with grated beetroot mixed through and a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler", "lunch_b": "Curd rice (thayir sadam) with grated beetroot mixed through, a light tempering of finely ground mustard seed and curry leaf, with any whole seeds strained out before serving to the toddler, and a small portion of fully cooked, lower-mercury fish, finely flaked and carefully checked for bones", "nourishment_break_a": "A small bowl of curd with soft, ripe jamun (Indian black plum), skin and seed removed, finely mashed", "nourishment_break_b": "Watermelon seed, ground to a smooth powder and mixed thoroughly into a small bowl of warm milk so no dry pieces remain, if watermelon seed has already been introduced and tolerated", "dinner_a": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped capsicum, mildly spiced), served with plain curd", "dinner_b": "Vegetable pulao (rice cooked with green peas, softened and lightly squashed, and finely chopped capsicum, mildly spiced) with soft tofu, finely crumbled, mixed through, served with plain curd, if soy has already been introduced and tolerated If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food.", "still_hungry": null}, {"day_number": 7, "title": "Bringing it together", "notes": "This week''s habit isn''t a set of drills — it''s simply continuing to offer a spoon and fork alongside food, letting your toddler use them, their fingers, or both, without pressure. Mess is part of the process, hand-eating is a legitimate skill of its own, and utensil neatness is something that keeps developing for years yet.", "breakfast_a": "Ragi dosa, soft, served with plain curd", "breakfast_b": "Ragi dosa, soft, served with a fully cooked hard-boiled egg, finely chopped, on the side", "lunch_a": "Soft roti with moong dal and soft-cooked cabbage, finely shredded", "lunch_b": "Soft roti with moong dal, a fully cooked egg curry and soft-cooked cabbage, finely shredded", "nourishment_break_a": "A small bowl of curd with soft, ripe lychee, peeled and pit removed, mashed or cut into very small flattened pieces appropriate to the toddler''s chewing skills", "nourishment_break_b": "Sabja (basil) seeds, soaked until softened and mixed thoroughly into a small bowl of plain curd so no dry pieces remain, if sabja seeds have already been introduced and tolerated", "dinner_a": "Soft khichdi with chana dal and soft-cooked green peas, lightly mashed", "dinner_b": "Soft khichdi with chana dal and soft-cooked green peas, lightly mashed, and a fully cooked hard-boiled egg, finely chopped, on the side If either of you is still hungry: Offer more of the meal, or choose curd, milk, fruit with a protein-rich accompaniment, or another suitable family food. Think about your toddler''s last few meals: did they try a spoon or fork at all, even messily? That ordinary, imperfect attempt is exactly what this stage looks like.", "still_hungry": null}]'::jsonb,
   'Notice this week whether thinking about your toddler''s utensil skills changed how you looked at a messy meal, or whether it mostly confirmed what you already sensed. Both are useful things to know about how you want to use this series going forward.',
   'Next week brings a new focus for your family''s table. Until then, this week doesn''t ask for anything more than the meals already on your plate.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 138: Biotin (vitamin B7), and the one lab-test detail worth remembering
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   138,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Biotin (vitamin B7), and the one lab-test detail worth remembering',
   '"Biotin supports everyday energy metabolism and is found in cooked egg yolk, nuts, seeds, sweet potato and mushrooms — deficiency is rare, hair/skin/nail supplement claims aren''t well supported for people who aren''t deficient, and the one genuine caution is telling your clinician or lab if you take a biotin supplement before any blood test, since it can skew certain results."',
   'Biotin (vitamin B7) is a B vitamin your body uses as part of everyday energy metabolism. Cooked egg yolk, nuts, seeds, sweet potato, mushrooms and whole grains are all reliable sources, and a genuine dietary deficiency is uncommon. One specific detail worth knowing: raw or very undercooked egg white, eaten regularly in large amounts, contains a protein that binds biotin and can reduce absorption — cooking eggs fully, already this series'' standard food-safety guidance, avoids this. Biotin is widely marketed in hair, skin and nail supplements, though the evidence for a meaningful benefit in people who aren''t deficient is limited. The one genuinely important safety point is about supplements, not food: biotin supplements can interfere with certain lab tests, including thyroid function and cardiac troponin tests, producing misleading results. Tell the healthcare team about any biotin-containing supplement, including the dose and when you last took it, before a blood test — but don''t delay urgent care to do so, and follow their instructions about whether to pause it.',
   'If you manage diabetes or another condition affecting blood sugar: follow your own care team''s specific guidance on portions and timing — the A and B meal options here aren''t matched for carbohydrate content either. If you have PCOS: flexible, balanced eating across the week matters more than any single "PCOS diet" — there''s no special curative diet required, and the general guidance in this series applies to you too. If you take levothyroxine: follow your prescribed timing around meals, calcium-rich foods, and calcium or iron supplements — ask your pharmacist if you''re unsure about spacing. If you take a biotin supplement and have a blood test coming up: tell your clinician and the lab, including the dose and when you last took it — biotin can interfere with certain results, including thyroid and cardiac troponin tests. Follow their instructions about whether to pause it, and don''t delay urgent care to do this. These notes are general starting points, not condition-specific menus — the meal options below aren''t matched to any particular condition''s nutrient or carbohydrate targets. Individual guidance from your own care team always takes precedence.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here. If you are pregnant or breastfeeding and eat fish, FDA/EPA guidance recommends two to three adult servings weekly from its "Best Choices" list — about 113 g per serving before cooking. Follow local advisories. This is an option for fish eaters, not a requirement to add fish.',
   'Choose either option, not both — these are alternatives, not two separate meals. Repeating a combination you already enjoyed earlier in the week is completely fine. If nothing here appeals or you''d rather keep it simple, reheated dal, rice and curd is an option if it suits your dietary needs and any care plan you follow. The "if you''re still hungry" suggestions are suggestions, not limits — adjust everything to your own appetite; this week''s meals are meant to be adequate, not restrictive. The "A" options are vegetarian, prepared with vegetable stock or water rather than meat or fish stock, including this week''s regional dishes. Portions below are adjustable starting points, not maximum allowances — scale to your own appetite, activity and any care plan you follow. A cup means a standard 240ml measuring cup. Unless a dish says otherwise: rice or another cooked grain eaten on its own is one level cup (about 150g); a dal, bean or lentil curry eaten as its own dish is three-quarters of a cup cooked (about 150g); a roti is one medium piece; toast is 2 slices. In a mixed rice or grain dish, the meat, fish, paneer or legume component is about 75-100g of that ingredient (roughly a palm-sized piece, or half a cup of cooked legumes), counted separately from the grain itself. Paneer, tofu, meat or fish eaten as a dish''s main item is 75-100g cooked (a palm-sized piece), or two eggs — these are different foods with different nutrient content, and are not nutritionally interchangeable just because they share a similar portion size. Curd or milk is a small bowl or glass (150-200ml); a cooked vegetable side is about a cup; nuts or seeds used as a topping are about a tablespoon (roughly 10-15g). The meals contribute different nutrients across the day; each individual meal or snack does not need to include every food group. Choose varied meals through the day and include a dependable protein source and a dependable calcium source at more than one meal — curd, milk or paneer — rather than relying on trace amounts in mixed dishes or an optional extra. If you avoid dairy, include measured portions of calcium-fortified alternatives or calcium-set tofu, checking the label. Adults generally need about 1,000 mg of calcium a day, including while breastfeeding — a single measured serving is a helpful building block, not the whole day''s requirement on its own. Food choices alone don''t rule out a need for supplementation — ask your own clinician what''s right for you. This week''s meals draw on Purvanchal/Bhojpuri home cooking (poori-chokha, bharwa baingan, dal-poori, and similar), using moong, masoor, toor and chana dal rather than khesari (grass pea) dal — khesari''s β-ODAP content is best avoided in a standard weekly menu. If a regional dish is unfamiliar or unavailable, choose a familiar alternative with a similar nutritional role: dal or beans for a legume dish, a suitable protein source for a protein dish, and vegetables for a vegetable side. Keep the grain portion and any planned calcium source. These swaps are not nutritionally identical.',
   '[{"day_number": 1, "title": "Anchor", "notes": "Biotin (vitamin B7) is another B vitamin your body uses as part of everyday energy metabolism. It''s found in cooked egg yolk, nuts, seeds, sweet potato, mushrooms and whole grains, among other foods, and a genuine deficiency is uncommon with a varied diet.", "breakfast_a": "Poori (2 pieces) with aloo-baingan chokha and a small bowl of curd (150g)", "breakfast_b": "Egg bhurji, spiced scrambled eggs (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Masoor dal (1 cup, includes a measured 1/2 cup cooked masoor dal) with rice (1 cup cooked) and a bharwa baingan", "lunch_b": "Poorbi mutton curry (100g mutton) with rice (1 cup cooked) and a bharwa baingan", "nourishment_break_a": "A small bowl of curd (150g) with a banana", "nourishment_break_b": "A glass of milk (200ml) with roasted peanuts (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a moong dal (3/4 cup) and a lauki sabzi", "dinner_b": "Paneer-and-tomato curry (100g paneer) with rice (1 cup cooked) and a beans sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 2, "title": "Cooked egg yolk is a good source — cooked egg white matters too", "notes": "Egg yolk, once cooked, is a reliable everyday biotin source. This is one of the few places in this series where a specific cooking detail connects directly to a nutrient — another good reason, alongside food safety, to cook eggs fully rather than eating them raw or very undercooked. Worth knowing: Eating a large amount of raw or undercooked egg white regularly can bind biotin and reduce how much your body absorbs, because raw egg white contains a protein (avidin) that binds it. Cooking eggs fully — already this series'' standard food-safety guidance, avoiding runny yolks — inactivates avidin and avoids this altogether.", "breakfast_a": "Sattu paratha, roasted gram-flour stuffed flatbread (2 pieces) with a small bowl of curd (150g) and a pickle", "breakfast_b": "Boiled eggs (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Bharwa baingan with toor dal (1 cup, includes a measured 1/2 cup cooked toor dal) with rice (1 cup cooked)", "lunch_b": "Poorbi chicken curry (100g chicken) with rice (1 cup cooked) and a bharwa baingan", "nourishment_break_a": "A small bowl of curd (150g) with a cup of cut papaya", "nourishment_break_b": "A glass of milk (200ml) with roasted almonds (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a chana dal (3/4 cup) and a bhindi sabzi", "dinner_b": "Egg curry, poorbi-style (2 eggs) with rice (1 cup cooked) and a cauliflower sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 3, "title": "Hair, skin and nail supplement claims, kept in perspective", "notes": "Biotin is widely marketed in hair, skin and nail supplements. For people who already get enough biotin from food and aren''t deficient, the evidence that extra biotin meaningfully improves hair or nail growth is limited — a varied diet already covers most people''s needs without an additional supplement.", "breakfast_a": "Chuda-dahi, flattened rice with curd and jaggery (1 cup flattened rice, measured dry before soaking; 150g curd)", "breakfast_b": "Egg-and-onion paratha (2 eggs, 2 paratha) with a glass of milk (200ml)", "lunch_a": "Moong dal with bharwa baingan (1 cup, includes a measured 1/2 cup cooked moong dal) with rice (1 cup cooked)", "lunch_b": "Poorbi mutton curry (100g mutton) with rice (1 cup cooked) and a lauki sabzi", "nourishment_break_a": "A small bowl of curd (150g) with a guava", "nourishment_break_b": "A glass of milk (200ml) with roasted chana (15g) and a piece of seasonal fruit", "dinner_a": "Dal-poori (2 pieces, includes a measured 1/2 cup cooked chana dal filling) with a small bowl of curd (150g) and a bhindi sabzi", "dinner_b": "Paneer-and-peas curry (100g paneer) with rice (1 cup cooked) and a carrot sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 4, "title": "If you take a biotin supplement and need a blood test", "notes": "This is the one genuinely important safety point about biotin, and it''s about supplements, not food — mention any biotin supplement before routine or urgent blood work, especially thyroid tests or, in an emergency setting, cardiac tests. Urgent care always comes first; the supplement detail can be mentioned as soon as it''s practical to do so. Worth knowing: Biotin supplements, including many hair/skin/nail products and some multivitamins, can interfere with certain lab tests — including thyroid function tests and cardiac troponin tests — producing falsely abnormal or falsely normal results. Tell your clinician and the lab about any biotin-containing supplement, including the dose and when you last took it, and follow their instructions about whether to pause it. Don''t delay urgent care to do this.", "breakfast_a": "Poori with mixed vegetable chokha (2 pieces) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-spinach bhurji (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Bharwa baingan with rice (1 cup rice) and a chana dal (includes a measured 1/2 cup cooked chana dal)", "lunch_b": "Poorbi chicken curry (100g chicken) with rice (1 cup cooked) and a lauki sabzi", "nourishment_break_a": "A small bowl of curd (150g) with a pear", "nourishment_break_b": "A glass of milk (200ml) with roasted walnuts (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a masoor dal (3/4 cup) and a spinach sabzi", "dinner_b": "Egg curry, poorbi-style (2 eggs) with rice (1 cup cooked) and a mushroom sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 5, "title": "Good options if you eat mostly vegetarian", "notes": "Nuts, seeds, sweet potato, mushrooms, whole grains and legumes all contribute biotin without needing meat, fish or eggs — a plant-forward day covers this comfortably as long as it includes some variety across these groups.", "breakfast_a": "Besan cheela, gram-flour pancake (2 pieces) with green chutney and a small bowl of curd (150g)", "breakfast_b": "Egg-and-vegetable sandwich (2 eggs, 2 slices bread) with a glass of milk (200ml)", "lunch_a": "Toor dal (1 cup, includes a measured 1/2 cup cooked toor dal) with rice (1 cup cooked) and a mushroom sabzi", "lunch_b": "Poorbi-style rohu fish curry (100g fish) with rice (1 cup cooked) and a bharwa baingan", "nourishment_break_a": "A small bowl of curd (150g) with an orange", "nourishment_break_b": "A glass of milk (200ml) with roasted cashews (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with an urad dal (3/4 cup) and a cauliflower sabzi", "dinner_b": "Paneer-and-capsicum curry (100g paneer) with rice (1 cup cooked) and a carrot sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 6, "title": "The pattern across your week matters, not one meal", "notes": "One meal without an obvious biotin source doesn''t change anything meaningfully — as with the other B vitamins this series has covered, it''s the overall pattern of varied meals across the week, not any single plate, that matters.", "breakfast_a": "Vegetable daliya, cracked wheat porridge with mixed vegetables (1 cup) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-tomato bhurji (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a masoor dal (1 cup, includes a measured 1/2 cup cooked masoor dal) and a bharwa baingan", "lunch_b": "Poorbi mutton curry (100g mutton) with rice (1 cup cooked) and a beans-and-carrot sabzi", "nourishment_break_a": "A small bowl of curd (150g) with a cup of cut watermelon", "nourishment_break_b": "A glass of milk (200ml) with a few dates", "dinner_a": "Moong dal-and-vegetable khichdi with mushrooms and peas (1 1/2 cups total, made with a measured 1/2 cup cooked rice and a measured 1/2 cup cooked moong dal, plus the vegetables) with a small bowl of curd (150g)", "dinner_b": "Poorbi chicken curry (100g chicken) with rice (1 cup cooked) and a spinach sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 7, "title": "A repeat-favourites day", "notes": "No forced choices today. Day 1''s combination is repeated below as a ready option — or swap in whichever meals from earlier in the week worked best for you. Looking back across this run of weeks, which single change has made the most noticeable difference to how you feel day to day?", "breakfast_a": "Poori (2 pieces) with aloo-baingan chokha and a small bowl of curd (150g)", "breakfast_b": "Egg bhurji, spiced scrambled eggs (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Masoor dal (1 cup, includes a measured 1/2 cup cooked masoor dal) with rice (1 cup cooked) and a bharwa baingan", "lunch_b": "Poorbi mutton curry (100g mutton) with rice (1 cup cooked) and a bharwa baingan", "nourishment_break_a": "A small bowl of curd (150g) with a banana", "nourishment_break_b": "A glass of milk (200ml) with roasted peanuts (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a moong dal (3/4 cup) and a lauki sabzi", "dinner_b": "Paneer-and-tomato curry (100g paneer) with rice (1 cup cooked) and a beans sabzi", "still_hungry": "A small bowl of curd (150g)"}]'::jsonb,
   'What''s one small habit from this week — a food, a routine — that felt worth keeping, without needing to overhaul everything at once?',
   'The next set of weeks continues this series'' steady, one-topic-at-a-time approach to your own nutrition and wellbeing.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 139: Cooking once for a household with different food habits or needs
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   139,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Cooking once for a household with different food habits or needs',
   '"One meal doesn''t have to become several — a shared base you finish or season differently at the edges still leaves room for your own appetite, protein and portion, without cooking a separate dish just for yourself."',
   'If your household includes people who eat differently from you — a vegetarian elder, someone who can''t manage much spice, different portion needs — you may already be doing more planning at mealtimes than you''re given credit for. Building meals around a shared base that you adapt at the end, rather than cooking several separate dishes, can genuinely reduce the work, but it can also quietly become a habit where your own plate is whatever''s simplest or whatever''s left over. This week is about keeping your own protein, portion and calcium part of that planning, not an afterthought to everyone else''s. None of this requires cooking separately for yourself — it''s mostly about sequencing: setting your own portion aside, finishing your own plate''s seasoning, before the rest of the household is served.',
   'If you manage diabetes or another condition affecting blood sugar: follow your own care team''s specific guidance on portions and timing — the A and B meal options here aren''t matched for carbohydrate content either. If you have PCOS: flexible, balanced eating across the week matters more than any single "PCOS diet" — there''s no special curative diet required, and the general guidance in this series applies to you too. If you take levothyroxine: follow your prescribed timing around meals, calcium-rich foods, and calcium or iron supplements — ask your pharmacist if you''re unsure about spacing. If you''re cooking a reduced-spice or reduced-salt version of a dish for someone else in the household: your own portion doesn''t need to match theirs unless you have your own reason to eat that way — season or finish your own plate separately once the shared base is cooked. These notes are general starting points, not condition-specific menus — the meal options below aren''t matched to any particular condition''s nutrient or carbohydrate targets. Individual guidance from your own care team always takes precedence.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here. If you are pregnant or breastfeeding and eat fish, FDA/EPA guidance recommends two to three adult servings weekly from its "Best Choices" list — about 113 g per serving before cooking. Follow local advisories. This is an option for fish eaters, not a requirement to add fish.',
   'Choose either option, not both — these are alternatives, not two separate meals. Repeating a combination you already enjoyed earlier in the week is completely fine. If nothing here appeals or you''d rather keep it simple, reheated dal, rice and curd is an option if it suits your dietary needs and any care plan you follow. The "if you''re still hungry" suggestions are suggestions, not limits — adjust everything to your own appetite; this week''s meals are meant to be adequate, not restrictive. The "A" options are vegetarian, prepared with vegetable stock or water rather than meat or fish stock, including this week''s regional dishes. Portions below are adjustable starting points, not maximum allowances — scale to your own appetite, activity and any care plan you follow. A cup means a standard 240ml measuring cup. Unless a dish says otherwise: rice or another cooked grain eaten on its own is one level cup (about 150g); a dal, bean or lentil curry eaten as its own dish is three-quarters of a cup cooked (about 150g); a roti is one medium piece; toast is 2 slices. In a mixed rice or grain dish, the meat, fish, paneer or legume component is about 75-100g of that ingredient (roughly a palm-sized piece, or half a cup of cooked legumes), counted separately from the grain itself. Paneer, tofu, meat or fish eaten as a dish''s main item is 75-100g cooked (a palm-sized piece), or two eggs — these are different foods with different nutrient content, and are not nutritionally interchangeable just because they share a similar portion size. Curd or milk is a small bowl or glass (150-200ml); a cooked vegetable side is about a cup; nuts or seeds used as a topping are about a tablespoon (roughly 10-15g). The meals contribute different nutrients across the day; each individual meal or snack does not need to include every food group. Choose varied meals through the day and include a dependable protein source and a dependable calcium source at more than one meal — curd, milk or paneer — rather than relying on trace amounts in mixed dishes or an optional extra. If you avoid dairy, include measured portions of calcium-fortified alternatives or calcium-set tofu, checking the label. Adults generally need about 1,000 mg of calcium a day, including while breastfeeding — a single measured serving is a helpful building block, not the whole day''s requirement on its own. Food choices alone don''t rule out a need for supplementation — ask your own clinician what''s right for you. This week''s meals draw on Konkani Goud Saraswat Brahmin home cooking (sol kadhi, ambat, upkari, dalitoy, khotto, and similar). If a regional dish is unfamiliar or unavailable, choose a familiar alternative with a similar nutritional role: dal or beans for a legume dish, a suitable protein source for a protein dish, and vegetables for a vegetable side. Keep the grain portion and any planned calcium source. These swaps are not nutritionally identical.',
   '[{"day_number": 1, "title": "Anchor", "notes": "Cooking for a household where people eat differently — a vegetarian elder, someone who can''t take much spice, different portion needs — often means building meals around everyone else first. A shared base you adapt at the end, rather than cooking multiple separate dishes, can save real effort while still leaving room for your own plate to be complete.", "breakfast_a": "Sanna polo, soft rice-and-coconut pancake (2 pieces) with a small bowl of curd (150g)", "breakfast_b": "Egg bhurji, spiced scrambled eggs (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Dalitoy, plain toor dal (1 cup, includes a measured 1/2 cup cooked toor dal) with rice (1 cup cooked) and an upkari (stir-fried cabbage)", "lunch_b": "Kori ambat, Konkani-style chicken curry (100g chicken) with rice (1 cup cooked) and an upkari (stir-fried cabbage)", "nourishment_break_a": "A small bowl of curd (150g) with a banana", "nourishment_break_b": "A glass of milk (200ml) with roasted cashews (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a moong dal (3/4 cup) and a beans upkari", "dinner_b": "Paneer-and-tomato curry (100g paneer) with rice (1 cup cooked) and a beans upkari", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 2, "title": "Cooking one base, then splitting it at the end", "notes": "A shared vegetable or dal base — cooked plain first, then divided before adding chilli, extra spice or a non-vegetarian addition to individual portions — is often quicker than starting several dishes from scratch. Set aside the vegetarian portions before adding any meat or fish, and make sure any meat or fish addition is cooked through fully rather than just warmed in the shared base. Your own portion can be the one that gets a full protein addition, rather than automatically becoming the plainest one on the table.", "breakfast_a": "Neer dosa (3 pieces) with a coconut chutney and a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Ambat, coconut-based vegetable curry (1 cup) with rice (1 cup cooked) and a chana dal (3/4 cup)", "lunch_b": "Konkani fish curry (100g fish) with rice (1 cup cooked) and an ambat, coconut-based vegetable curry (1 cup)", "nourishment_break_a": "A small bowl of curd (150g) with a cup of cut papaya", "nourishment_break_b": "A glass of milk (200ml) with roasted peanuts (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a masoor dal (3/4 cup) and a bhindi upkari", "dinner_b": "Egg curry, Konkani-style (2 eggs) with rice (1 cup cooked) and a bhindi upkari", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 3, "title": "Protecting your own portion when food is served family-style", "notes": "Family-style serving can mean the person cooking, and often serving, ends up eating whatever''s left rather than a planned portion. Setting your own plate aside before the rest of the household starts serving themselves is a small, practical habit, not a sign you''re being unfair to anyone else at the table. Worth knowing: When a meal is served from shared serving dishes rather than individually plated, it''s easy for your own portion to end up smaller than planned, especially once everyone else has been served first. Plating your own protein and grain portion before the dish goes to the table, or serving yourself early rather than last, is a practical way to make sure your plate is complete too.", "breakfast_a": "Sanna polo with grated coconut (2 pieces) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-tomato omelette (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Dalitoy with pumpkin (1 cup, includes a measured 1/2 cup cooked toor dal) with rice (1 cup cooked)", "lunch_b": "Kori ambat (100g chicken) with rice (1 cup cooked) and a cauliflower upkari", "nourishment_break_a": "A small bowl of curd (150g) with a guava", "nourishment_break_b": "A glass of milk (200ml) with roasted almonds (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a toor dal (3/4 cup) and a cauliflower upkari", "dinner_b": "Paneer-and-peas curry (100g paneer) with rice (1 cup cooked) and a carrot upkari", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 4, "title": "Adjusting flavour for others, not your own portion", "notes": "Cooking blander for a family member who needs it — an elder, someone with a digestive condition — doesn''t mean your own plate has to match. Keep your portion and protein adequate. Adjust flavour to your preference once the base is cooked; extra salt is not necessary.", "breakfast_a": "Suji upma with mixed vegetables (1 cup) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-spinach bhurji (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Ambat with raw banana (1 cup) with rice (1 cup cooked) and a moong dal (3/4 cup)", "lunch_b": "Kori ambat (100g chicken) with rice (1 cup cooked) and a beans upkari", "nourishment_break_a": "A small bowl of curd (150g) with a pear", "nourishment_break_b": "A glass of milk (200ml) with roasted walnuts (15g) and a piece of seasonal fruit", "dinner_a": "Sanna polo (2 pieces) with a chana dal (3/4 cup) and a spinach upkari", "dinner_b": "Egg curry, Konkani-style (2 eggs) with sanna polo (2 pieces) and a spinach upkari", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 5, "title": "Big-batch communal cooking — a puja, a gathering", "notes": "Cooking in large quantities for a gathering or a puja day is a different scale of effort, and it''s easy to end up eating irregularly, or mostly leftovers, while everyone else is served properly. Setting aside your own plate, with a full portion of whatever protein is being served, before the serving starts is worth doing on these days especially.", "breakfast_a": "Neer dosa with jaggery (3 pieces) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-vegetable sandwich (2 eggs, 2 slices bread) with a glass of milk (200ml)", "lunch_a": "Khotto, steamed vegetable-and-lentil cakes (2 pieces) with an ambat (1 cup)", "lunch_b": "Khotto, steamed vegetable-and-lentil cakes (2 pieces) with a Kori ambat, Konkani-style chicken curry (100g chicken)", "nourishment_break_a": "A small bowl of curd (150g) with an orange", "nourishment_break_b": "A glass of milk (200ml) with roasted makhana (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with an urad dal (3/4 cup) and a carrot upkari", "dinner_b": "Konkani fish ambot-tik, tangy-spicy fish curry (100g fish) with rice (1 cup cooked) and a carrot upkari", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 6, "title": "The pattern across your week matters, not one meal", "notes": "Some days, cooking for a mixed household still means your own plate ends up smaller or simpler than planned — that''s a realistic part of running a kitchen for more than one person, not a failure to manage it perfectly. What matters is that across most of the week, your own portion, protein and calcium are getting the same planning as everyone else''s.", "breakfast_a": "Suji upma with grated carrot (1 cup) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-onion bhurji (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Dalitoy (1 cup, includes a measured 1/2 cup cooked toor dal) with rice (1 cup cooked) and an upkari (stir-fried beans and carrot)", "lunch_b": "Kori ambat (100g chicken) with rice (1 cup cooked) and an upkari (stir-fried beans and carrot)", "nourishment_break_a": "A small bowl of curd (150g) with a cup of cut watermelon", "nourishment_break_b": "A glass of milk (200ml) with a few dates", "dinner_a": "Moong dal-and-vegetable khichdi (1 1/2 cups total, made with a measured 1/2 cup cooked rice and a measured 1/2 cup cooked moong dal, plus carrots and peas) with a small bowl of curd (150g)", "dinner_b": "Egg curry, Konkani-style (2 eggs) with rice (1 cup cooked) and a cabbage upkari", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 7, "title": "A repeat-favourites day", "notes": "No forced choices today. Day 1''s combination is repeated below as a ready option — or swap in whichever meals from earlier in the week worked best for you. Was there a moment this week you deliberately set your own portion aside before serving everyone else — and how did that change the rest of your day?", "breakfast_a": "Sanna polo, soft rice-and-coconut pancake (2 pieces) with a small bowl of curd (150g)", "breakfast_b": "Egg bhurji, spiced scrambled eggs (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Dalitoy, plain toor dal (1 cup, includes a measured 1/2 cup cooked toor dal) with rice (1 cup cooked) and an upkari (stir-fried cabbage)", "lunch_b": "Kori ambat, Konkani-style chicken curry (100g chicken) with rice (1 cup cooked) and an upkari (stir-fried cabbage)", "nourishment_break_a": "A small bowl of curd (150g) with a banana", "nourishment_break_b": "A glass of milk (200ml) with roasted cashews (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a moong dal (3/4 cup) and a beans upkari", "dinner_b": "Paneer-and-tomato curry (100g paneer) with rice (1 cup cooked) and a beans upkari", "still_hungry": "A small bowl of curd (150g)"}]'::jsonb,
   'What''s one small habit from this week — a food, a routine — that felt worth keeping, without needing to overhaul everything at once?',
   'The next set of weeks continues this series'' steady, one-topic-at-a-time approach to your own nutrition and wellbeing.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 140: Eating well on badly-slept nights and the tired days after
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   140,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Eating well on badly-slept nights and the tired days after',
   '"A rough night makes the pull toward something quick and sugary feel stronger than usual — that''s a real physiological response, not a lack of willpower. Having a few steady, low-effort options ready matters more on these days than on any other."',
   'Broken or short sleep can change appetite and make convenient, energy-dense foods more appealing, while the effort of cooking or planning a balanced meal can feel like more than you have energy for. If you notice yourself reaching harder for quick options or skipping meals after a bad night, that''s a recognised response to sleep loss, not a personal failing. This week focuses on having a few steady, low-effort options ready for the days that follow a rough night — food that needs little preparation, still includes protein, and doesn''t require willpower you may not have to spare that day.',
   'If you manage diabetes or another condition affecting blood sugar: follow your own care team''s specific guidance on portions and timing — the A and B meal options here aren''t matched for carbohydrate content either. If you have PCOS: flexible, balanced eating across the week matters more than any single "PCOS diet" — there''s no special curative diet required, and the general guidance in this series applies to you too. If you take levothyroxine: follow your prescribed timing around meals, calcium-rich foods, and calcium or iron supplements — ask your pharmacist if you''re unsure about spacing. If poor sleep is a frequent, ongoing pattern rather than occasional: it''s worth mentioning to your own healthcare team — this week''s suggestions are about eating through tired days, not a substitute for addressing persistent sleep problems. These notes are general starting points, not condition-specific menus — the meal options below aren''t matched to any particular condition''s nutrient or carbohydrate targets. Individual guidance from your own care team always takes precedence.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here. If you are pregnant or breastfeeding and eat fish, FDA/EPA guidance recommends two to three adult servings weekly from its "Best Choices" list — about 113 g per serving before cooking. Follow local advisories. This is an option for fish eaters, not a requirement to add fish.',
   'Choose either option, not both — these are alternatives, not two separate meals. Repeating a combination you already enjoyed earlier in the week is completely fine. If nothing here appeals or you''d rather keep it simple, reheated dal, rice and curd is an option if it suits your dietary needs and any care plan you follow. The "if you''re still hungry" suggestions are suggestions, not limits — adjust everything to your own appetite; this week''s meals are meant to be adequate, not restrictive. The "A" options are vegetarian, prepared with vegetable stock or water rather than meat or fish stock, including this week''s regional dishes. Portions below are adjustable starting points, not maximum allowances — scale to your own appetite, activity and any care plan you follow. A cup means a standard 240ml measuring cup. Unless a dish says otherwise: rice or another cooked grain eaten on its own is one level cup (about 150g); a dal, bean or lentil curry eaten as its own dish is three-quarters of a cup cooked (about 150g); a roti is one medium piece; toast is 2 slices. In a mixed rice or grain dish, the meat, fish, paneer or legume component is about 75-100g of that ingredient (roughly a palm-sized piece, or half a cup of cooked legumes), counted separately from the grain itself. Paneer, tofu, meat or fish eaten as a dish''s main item is 75-100g cooked (a palm-sized piece), or two eggs — these are different foods with different nutrient content, and are not nutritionally interchangeable just because they share a similar portion size. Curd or milk is a small bowl or glass (150-200ml); a cooked vegetable side is about a cup; nuts or seeds used as a topping are about a tablespoon (roughly 10-15g). The meals contribute different nutrients across the day; each individual meal or snack does not need to include every food group. Choose varied meals through the day and include a dependable protein source and a dependable calcium source at more than one meal — curd, milk or paneer — rather than relying on trace amounts in mixed dishes or an optional extra. If you avoid dairy, include measured portions of calcium-fortified alternatives or calcium-set tofu, checking the label. Adults generally need about 1,000 mg of calcium a day, including while breastfeeding — a single measured serving is a helpful building block, not the whole day''s requirement on its own. Food choices alone don''t rule out a need for supplementation — ask your own clinician what''s right for you. This week''s meals draw on Assamese home cooking (tenga, khar, pitika, masor jool, and similar). If a regional dish is unfamiliar or unavailable, choose a familiar alternative with a similar nutritional role: dal or beans for a legume dish, a suitable protein source for a protein dish, and vegetables for a vegetable side. Keep the grain portion and any planned calcium source. These swaps are not nutritionally identical.',
   '[{"day_number": 1, "title": "Anchor", "notes": "Poor sleep can change appetite and make convenient foods more appealing. Easy meals and snacks can help you eat regularly on tired days. Recognising that pull as a normal response to short sleep, rather than a failure of discipline, is the starting point for working with it instead of against it.", "breakfast_a": "Chira pitika, flattened rice mashed with curd and banana (1 cup) with a small portion of paneer (50g)", "breakfast_b": "Peanut butter toast (2 slices, 1 tablespoon peanut butter) with a glass of milk (200ml) and a banana", "lunch_a": "Khar, raw papaya and lentil dish (1 cup) with rice (1 cup cooked) and a masoor dal (3/4 cup)", "lunch_b": "Paneer-and-tomato curry (100g paneer) with rice (1 cup cooked) and a khar vegetable side", "nourishment_break_a": "A small bowl of curd (150g) with a banana", "nourishment_break_b": "A glass of milk (200ml) with roasted chana (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a moong dal (3/4 cup) and a pumpkin sabzi", "dinner_b": "Chicken curry, Assamese-style (100g chicken) with rice (1 cup cooked) and a pumpkin sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 2, "title": "Reaching for something quick on tired days", "notes": "On very little sleep, the easiest thing to reach for is often something sweet and fast — and that''s completely fine. If you''d like a steadier option alongside it, pairing fruit with a few nuts is one way to do that; it isn''t a rule, and fruit on its own is a perfectly good choice too.", "breakfast_a": "Suji upma with vegetables (1 cup) with a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Bor dal, split gram with vegetables (1 cup, includes a measured 1/2 cup cooked chana dal) with rice (1 cup cooked)", "lunch_b": "Assamese fish tenga, tangy fish curry (100g fish) with rice (1 cup cooked) and a bhindi pitika", "nourishment_break_a": "A small bowl of curd (150g) with a cup of cut apple", "nourishment_break_b": "A glass of milk (200ml) with roasted almonds (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a toor dal (3/4 cup) and a cabbage pitika", "dinner_b": "Egg curry, Assamese-style (2 eggs) with rice (1 cup cooked) and a cabbage pitika", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 3, "title": "No-cook and low-effort options for the hardest days", "notes": "Some days genuinely don''t have the energy for a stove. Curd with fruit and nuts, a boiled-egg sandwich, or a measured glass of milk with roasted chana are options that need little or no cooking and can count as a legitimate small meal, without needing to be a fully balanced plate every time. Worth knowing: On days when even simple cooking feels like too much, having two or three no-cook or minimal-effort combinations already in mind — rather than deciding from scratch while exhausted — can be the difference between eating something adequate and skipping meals or reaching for whatever''s fastest.", "breakfast_a": "Chira with curd and jaggery (1 cup flattened rice, measured dry before soaking; 150g curd)", "breakfast_b": "Egg sandwich (2 eggs, 2 slices bread) with a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a masoor dal (3/4 cup) and a khar vegetable side", "lunch_b": "Chicken curry, Assamese-style (100g chicken) with rice (1 cup cooked) and a beans pitika", "nourishment_break_a": "A small bowl of curd (150g) with a pear", "nourishment_break_b": "A glass of milk (200ml) with roasted walnuts (15g) and a piece of seasonal fruit", "dinner_a": "Chana dal-and-vegetable khichdi (1 1/2 cups total, made with a measured 1/2 cup cooked rice and a measured 1/2 cup cooked chana dal, plus spinach) with a small bowl of curd (150g)", "dinner_b": "Paneer-and-tomato curry (100g paneer) with rice (1 cup cooked) and a spinach pitika", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 4, "title": "Protein at breakfast matters more, not less, on tired mornings", "notes": "It''s tempting to skip breakfast or grab only something sweet on a groggy morning, but a protein-containing breakfast tends to blunt the mid-morning crash that makes an already tired day feel harder. It doesn''t need to be elaborate — eggs, curd, or a glass of milk alongside whatever''s quickest all count.", "breakfast_a": "Pitika, mashed potato with mustard oil and vegetables (1 cup) with a small bowl of curd (150g)", "breakfast_b": "Egg bhurji, spiced scrambled eggs (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Khar with a moong dal (3/4 cup) and rice (1 cup cooked)", "lunch_b": "Egg curry, Assamese-style (2 eggs) with rice (1 cup cooked) and a lauki sabzi", "nourishment_break_a": "A small bowl of curd (150g) with a guava", "nourishment_break_b": "A glass of milk (200ml) with a few dates", "dinner_a": "Rice (1 cup cooked) with an urad dal (3/4 cup) and a carrot sabzi", "dinner_b": "Chicken curry, Assamese-style (100g chicken) with rice (1 cup cooked) and a carrot sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 5, "title": "Hydration and caffeine on very tired days", "notes": "It''s easy to under-drink water on an exhausting day and reach for extra caffeine instead. A little caffeine is fine within the usual limit, but it isn''t a substitute for water, and dehydration itself can make tiredness and headaches worse. Keeping a water bottle within reach through the day is a small, low-effort habit worth keeping even when everything else feels like too much.", "breakfast_a": "Luchi, deep-fried flatbread (2 pieces) with an aloo sabzi and a small bowl of curd (150g)", "breakfast_b": "Egg-and-vegetable omelette (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Bor dal with lauki (1 cup, includes a measured 1/2 cup cooked chana dal) with rice (1 cup cooked)", "lunch_b": "Assamese fish curry (100g fish) with rice (1 cup cooked) and a cauliflower pitika", "nourishment_break_a": "A small bowl of curd (150g) with an orange", "nourishment_break_b": "A glass of milk (200ml) with roasted makhana (15g) and a piece of seasonal fruit", "dinner_a": "A masoor dal-and-bhindi curry, cooked together (1 cup, includes a measured 3/4 cup cooked masoor dal) with rice (1 cup cooked)", "dinner_b": "Paneer-and-peas curry (100g paneer) with rice (1 cup cooked) and a bhindi sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 6, "title": "The pattern across broken nights matters, not one bad day", "notes": "A single badly-slept night and the sluggish day after it won''t undo a generally steady pattern of eating. What tends to matter more is whether the tired days start stacking up into a habit of skipped meals and mostly sugar — worth noticing if that starts happening, and worth being gentle with yourself about if it does happen sometimes.", "breakfast_a": "Suji upma with grated carrot (1 cup) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-onion bhurji (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rice (1 cup cooked) with a chana dal (3/4 cup) and a khar vegetable side", "lunch_b": "Chicken curry, Assamese-style (100g chicken) with rice (1 cup cooked) and a cabbage sabzi", "nourishment_break_a": "A small bowl of curd (150g) with a cup of cut watermelon", "nourishment_break_b": "A glass of milk (200ml) with roasted cashews (15g) and a piece of seasonal fruit", "dinner_a": "Moong dal-and-vegetable khichdi (1 1/2 cups total, made with a measured 1/2 cup cooked rice and a measured 1/2 cup cooked moong dal, plus carrots and peas) with a small bowl of curd (150g)", "dinner_b": "Egg curry, Assamese-style (2 eggs) with rice (1 cup cooked) and a spinach sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 7, "title": "A repeat-favourites day", "notes": "No forced choices today. Day 1''s combination is repeated below as a ready option — or swap in whichever meals from earlier in the week worked best for you. Which low-effort combination from this week would you keep on hand for the next rough night, even without thinking it through again?", "breakfast_a": "Chira pitika, flattened rice mashed with curd and banana (1 cup) with a small portion of paneer (50g)", "breakfast_b": "Peanut butter toast (2 slices, 1 tablespoon peanut butter) with a glass of milk (200ml) and a banana", "lunch_a": "Khar, raw papaya and lentil dish (1 cup) with rice (1 cup cooked) and a masoor dal (3/4 cup)", "lunch_b": "Paneer-and-tomato curry (100g paneer) with rice (1 cup cooked) and a khar vegetable side", "nourishment_break_a": "A small bowl of curd (150g) with a banana", "nourishment_break_b": "A glass of milk (200ml) with roasted chana (15g) and a piece of seasonal fruit", "dinner_a": "Rice (1 cup cooked) with a moong dal (3/4 cup) and a pumpkin sabzi", "dinner_b": "Chicken curry, Assamese-style (100g chicken) with rice (1 cup cooked) and a pumpkin sabzi", "still_hungry": "A small bowl of curd (150g)"}]'::jsonb,
   'What''s one small habit from this week — a food, a routine — that felt worth keeping, without needing to overhaul everything at once?',
   'The next set of weeks continues this series'' steady, one-topic-at-a-time approach to your own nutrition and wellbeing.')
